local config = {
  ui_story_5031_50310101_1_dialog_content = "สุภาพสตรี สุภาพบุรุษ และแขกจากทั่วทุกสารทิศ! ยินดีต้อนรับสู่<color=#FFB400>คณะละครสัตว์นักมายากลและผู้เฒ่าบิลล์</color>! ดิฉันชื่อ<color=#FFB400>เรนโบว์</color> พิธีกรของคุณในการแสดงค่ำคืนนี้ค่ะ!",
  ui_story_5031_50310101_2_dialog_content = "ทุกท่านที่ร่วมเดินทางกับเรือมรกตในค่ำคืนที่งดงามนี้ ล้วนเป็นแขกผู้มีเกียรติของคณะละครสัตว์ของเรา",
  ui_story_5031_50310101_3_dialog_content = "ขอให้ทุกท่านได้วางความกังวลเคร่งเครียดลงก่อน และเพลิดเพลินกับการแสดงสุดอัศจรรย์ของเราค่ะ",
  ui_story_5031_50310101_4_dialog_content = "การแสดงสุดตระการตาจากคณะละครสัตว์นักมายากลและผู้เฒ่าบิลล์จะท้าทายทุกเหตุผลและพาคุณเดินทางไปให้ไกลเหนือจินตนาการ!",
  ui_story_5031_50310101_5_dialog_content = "ช่วงเวลาอันน่าอัศจรรย์นี้เป็นของคุณกับฉัน และโลกทั้งใบ!",
  ui_story_5031_50310101_6_dialog_content = "เพื่อไม่ให้เสียเวลา มาต้อนรับแขกรับเชิญคนแรกของเรากันเลยค่ะ สามสาวพี่น้องนักกายกรรมผู้พิชิตความสูงเสียดฟ้า ผู้เชี่ยวชาญศิลปะชิงช้ายักษ์! โปรดให้การต้อนรับเมอรีลท์...",
  ui_story_5031_50310101_7_dialog_content = "ซับลี่...",
  ui_story_5031_50310101_8_dialog_content = "และฟริเม็ต...",
  ui_story_5031_50310101_9_dialog_content = "ขึ้นสู่เวทีค่ะ!",
  ui_story_5031_50310101_10_dialog_content = "โอ๊ะโอ เรนโบว์...? ตอนนี้อุปกรณ์ชิงช้าซ่อมอยู่ไม่ใช่เหรอ...?",
  ui_story_5031_50310101_11_dialog_content = "นั่นสิ ถึงพวกเราจะเก่งขนาดไหน แต่ยังไงก็บินบนฟ้าไม่ได้หรอกนะ",
  ui_story_5031_50310101_12_dialog_content = "ฮิฮิ... ที่จริงคือ ฉันฝึกฝนกับนักกล้ามประจำคณะละครสัตว์มาพักหนึ่งแล้ว",
  ui_story_5031_50310101_13_dialog_content = "ฉันน่าจะส่งพวกเธอสองคนขึ้นฟ้าไหวนะ!",
  ui_story_5031_50310101_14_dialog_content = "ย-อย่าทำแบบนั้นดีกว่ามั้ย มันอันตรายนะ... แล้วก็ อาจจะโดนคนอื่นบาดเจ็บด้วย...",
  ui_story_5031_50310101_15_dialog_content = "นี่ หัวหน้า พูดอะไรหน่อยสิ",
  ui_story_5031_50310101_16_dialog_content = "เราสวมชุดจริงซ้อมไม่ได้นะถ้าอุปกรณ์ยังไม่พร้อม!",
