  ui_story_5031_50310101_18_dialog_content = "ซับลี่... พูดแบบนั้นกับหัวหน้าคณะละครสัตว์เจโน่ไม่น่ารักเลยนะ",
  ui_story_5031_50310101_19_dialog_content = "หืมม? ฉันกำลังยุ่งน่า",
  ui_story_5031_50310101_20_dialog_content = "ในที่สุดอุปกรณ์ของเอลวิสก็มาถึงแล้ว ตอนนี้พวกนั้นกำลังเตรียมงานขั้นสุดท้ายให้อยู่",
  ui_story_5031_50310101_21_dialog_content = "ถ้าเธอสามคนไม่อยากซ้อม งั้นก็ไปพักผ่อนซะ",
  ui_story_5031_50310101_22_dialog_content = "เรนโบว์ ไปตามตัวประกอบคนนั้นมาที คนที่บอกว่าพูดกับสัตว์ได้น่ะ",
  ui_story_5031_50310101_23_dialog_content = "เด็กคนนั้นมาแทนคนฝึกสัตว์ที่ป่วยเพราะกินน้ำแข็งไสได้",
  ui_story_5031_50310101_24_dialog_content = "ได้เลย~",
  ui_story_5031_50310101_25_dialog_content = "พร้อมหรือยัง คุณฟีญ่า?",
  ui_story_5031_50310101_26_dialog_content = "ปะ-แป๊บนึงนะ!",
  ui_story_5031_50310101_27_dialog_content = "มานี่บิก้า! ช่วยมาตรงนี้ที!",
  ui_story_5031_50310101_28_dialog_content = "ไฮ",
  ui_story_5031_50310101_29_dialog_content = "เหมือนที่บอกนะบิก้า กระโดดแล้วก็ตีลังกาตกลงไหม?",
  ui_story_5031_50310101_30_dialog_content = "ไฮ!",
  ui_story_5031_50310101_31_dialog_content = "ขอร้องนะบิก้า! แค่ครั้งนี้ครั้งเดียว ช่วยฟังฉันหน่อยได้ไหม? หัวหน้าคณะละครสัตว์หน้าดุคนนั้นยังมองอยู่เลยนะ!",
  ui_story_5031_50310101_32_dialog_content = "ไฮ่!!",
  ui_story_5031_50310101_33_dialog_content = "โอ๊ย! ใจเย็นก่อนได้ไหม? ฉันยอมขอโทษก็ได้ จะได้เลิกกัดฉันสักที!",
  ui_story_5031_50310101_34_dialog_content = "พอแล้ว พอแล้ว พอแล้ว!!",
  ui_story_5031_50310101_35_dialog_content = "อะไรกันเนี่ย? ถ้าจะปรับความเข้าใจก็ไปทำนอกเวที อย่ารบกวนการซ้อมสิ!",
  ui_story_5031_50310101_36_dialog_content = "หัวหน้าคณะละครสัตว์เจโน่!",
  ui_story_5031_50310101_37_dialog_content = "ว่าไง? เธอกับเพื่อนใหม่แนะนำตัวกันเสร็จรึยัง?",
  ui_story_5031_50310101_38_dialog_content = "มันไม่ยอมฟังที่ฉันพูดเลยแม้แต่คำเดียว หัวหน้าคณะละครสัตว์เจโน่! สงสัยมีคนตามใจจนเพี้ยนไปแล้วเนี่ย!",
  ui_story_5031_50310101_39_dialog_content = "เธอว่าโดนตามใจจนเพี้ยนไปแล้วงั้นเรอะ?",
  ui_story_5031_50310101_40_dialog_content = "ใช่แล้ว! แถมเมื่อกี๊กัดฉันอย่างแรงเลยด้วย!",
  ui_story_5031_50310101_41_dialog_content = "อ๋อ อันนั้นปกติมากเลย",
  ui_story_5031_50310101_42_dialog_content = "ปกติเรอะ?!",
  ui_story_5031_50310101_43_dialog_content = "ในฐานะที่เป็นส่วนหนึ่งของคณะละครสัตว์ สัตว์พวกนี้ก็ได้รับสิทธิ์เหมือนทุกคนนั่นแหละ แปลว่าพวกมันมีอิสระที่จะปฏิเสธงานถ้าพวกมันรู้สึกไม่อยากทำ",
  ui_story_5031_50310101_44_dialog_content = "อะไรรรรรนะ?!",
  ui_story_5031_50310101_45_dialog_content = "คณะละครสัตว์นี้ไม่เหมือนที่ฉันเคยอ่านเจอในหนังสือเลย! ไม่ใกล้เคียงเลยด้วยซ้ำ!",
  ui_story_5031_50310101_46_dialog_content = "ละครสัตว์ในหนังสือมีแต่ทารุณสัตว์กันทั้งนั้น แล้วก็ใช้ความกลัวบังคับให้สัตว์ขึ้นแสดง คุณจะบอกว่าตัวเองไม่ทำแบบนั้นเลยเหรอ?",
  ui_story_5031_50310101_47_dialog_content = "อะไรทำให้เธอคิดแบบนั้นกันเนี่ย?",
  ui_story_5031_50310101_48_dialog_content = "ฉันไม่เห็นรู้เลยว่ามีวิธีการแบบนั้นมาก่อนเลย... ฉันหรือใครก็ตามแต่ จะไปทำร้ายพวกมันทำไม? ยังไงซะพวกมันก็ไม่ใช่แค่นักแสดง แต่เป็นเพื่อนที่เรารักและมีความสำคัญกับเรานะ",
  ui_story_5031_50310101_49_dialog_content = "ดูบิก้ากับขนนุ่มฟูของมันนี่สิ ใครจะไปอยากทำร้ายสัตว์ที่ล้ำค่าแบบนี้?",
  ui_story_5031_50310101_50_dialog_content = "ไฮ่!",
  ui_story_5031_50310101_51_dialog_content = "ยังไงก็ตาม คณะละครสัตว์ของฉันไม่มีวันทำร้ายสัตว์นักแสดงของเราแบบนั้นแน่นอน ไม่ว่าตอนนี้หรือตอนไหน",
  ui_story_5031_50310101_52_dialog_content = "นักฝึกสัตว์ทุกคนที่ออกมาแสดงต่อหน้าเธอสามารถหาวิธีชักนำให้สัตว์ออกมาแสดงได้ เธอเองก็ต้องหาวิธีของตัวเองให้ได้เหมือนกัน",
  ui_story_5031_50310101_53_dialog_content = "นะ-นี่คุณคิดว่าพูดกับใครอยู่หา!",
  ui_story_5031_50310101_54_dialog_content = "*กระซิก ๆ* ฉันจะบอกไว้เลยนะ ฉันชื่อฟีญ่า นักสัตว์มหัศจรรย์วิทยาที่ยิ่งใหญ่ที่สุดในโลก! ความสัมพันธ์ระหว่างฉันกับสัตว์มหัศจรรย์น่ะแข็งแกร่งกว่าใคร ๆ ทั้งนั้น!",
  ui_story_5031_50310101_55_dialog_content = "นี่... นี่ทำไมเธอถึง...",
  ui_story_5031_50310101_56_dialog_content = "ไม่ต้องห่วงนะ PlayerName การแสดงบัลเลต์ไม่ใช่เรื่องท้าทายสำหรับฉันหรอก",
  ui_story_5031_50310101_57_dialog_content = "ฉันไม่เคยคิดเลยว่าจะได้เห็นเธอเต้นบัลเลต์ คาร์ลีน",
  ui_story_5031_50310101_58_dialog_content = "บนยานโคลอสซัส ฉันได้ยินออโรเรียนจากลูโมโพลิสคนอื่น ๆ คุยกันว่าเธอเต้นบัลเลต์เก่งมาก มีคนเคยบอกว่าขนาดอาจารย์สอนบัลเลต์ยังทึ่งกับการแสดงของเธอเลยด้วยซ้ำ!",
  ui_story_5031_50310101_59_dialog_content = "จริงเหรอ? งั้นฉันก็อดตื่นเต้นไม่ได้เหมือนกันนะที่จะได้ดูเธอเต้น!",
  ui_story_5031_50310101_60_dialog_content = "PlayerName!!",
  ui_story_5031_50310101_61_dialog_content = "ฟีญ่า? เธอต้องไปซ้อมการแสดงฝึกสัตว์ไม่ใช่เหรอ? มาทำอะไรที่นี่เนี่ย?",
  ui_story_5031_50310101_62_dialog_content = "โฮ โฮ... สัตว์มหัศจรรย์เอาแต่ใจพวกนั้นทำฉันจะเป็นบ้าแล้วเนี่ย! พวกมันไม่ยอมฟังคำสั่งเลย เพราะพวกมันได้รับอนุญาตให้ไม่ต้องทำงานถ้าไม่อยากทำไงล่ะ!",
  ui_story_5031_50310101_63_dialog_content = "พอฉันคิดถึงเรื่องนั้น... แล้วมาคิดว่าอาจารย์ฉันเนี่ยจู้จี้ยังกับอะไรดี... ฉัน... ฉัน... โฮฮฮฮฮฮฮฮฮ!!!",
  ui_story_5031_50310101_64_dialog_content = "อะ-เอ๊ย ๆ ไม่เอา! อย่าร้องไห้นะฟีญ่า...",
  ui_story_5031_50310101_65_dialog_content = "เธอควรจะเป็นนักสัตว์มหัศจรรย์วิทยาที่ยิ่งใหญ่ที่สุดในโลกสิ จำได้ไหม?",
  ui_story_5031_50310101_66_dialog_content = "ฉันรู้น่า! แล้วทำไม \"นักสัตว์มหัศจรรย์วิทยาที่ยิ่งใหญ่ที่สุดในโลก\" ยังต้องลำบากตรากตรำกับงานที่อาจารย์สั่งด้วยเนี่ย?!",
  ui_story_5031_50310101_67_dialog_content = "พยายามไม่คิดเรื่องนี้ดีไหม? จำที่ปกติเธอชอบแกล้งฉันได้มั้ย? เรียกอีเนอร์จี้แบบนั้นกลับมาให้ได้สิ!",
  ui_story_5031_50310101_68_dialog_content = "หา!?",
  ui_story_5031_50310101_69_dialog_content = "คืองี้... จำความยากลำบากทั้งหลายที่เราฝ่าฟันมาด้วยกันได้ไหม? มันก็เพื่อให้เธอได้ทำความฝันสูงสุดให้เป็นจริงไงล่ะ!",
  ui_story_5031_50310101_70_dialog_content = "โฮ... ความฝันสูงสุดของฉัน... แล้วก็ความยากลำบากทั้งหลายที่เราฝ่าฟันมาด้วยกัน...",
  ui_story_5031_50310101_71_dialog_content = "<color=#e8d9bb>ทันทีที่ไปถึงเมืองฮาร์เบอร์</color>",
  ui_story_5031_50310101_72_dialog_content = "ขอบใจที่ชวนฉันกับไวซ์มาที่เมืองฮาร์เบอร์นะคาร์ลีน",
  ui_story_5031_50310101_73_dialog_content = "ที่นี่สวยมากเลย ทั้งเงียบทั้งสงบ... เหมาะสำหรับพักผ่อนหย่อนใจที่สุด!",
  ui_story_5031_50310101_74_dialog_content = "แล้วฉันก็ดีใจมากเลยที่ทุกคนมากันครบ!",
  ui_story_5031_50310101_75_dialog_content = "ด้วยความยินดี ช่วงนี้ทุกคนตั้งใจทำงานกันอย่างหนัก ฉันเลยคิดว่าเราทุกคนน่าจะได้พักกันสักหน่อย เพื่อฟื้นฟูร่างกายกับจิตใจน่ะ",
  ui_story_5031_50310101_76_dialog_content = "ครั้งก่อนที่มาเมืองฮาร์เบอร์ ฉันยังเป็นเด็กเล็ก ๆ อยู่เลย แต่เมืองนี้ก็สร้างความประทับใจให้ฉันได้ไม่ต่างกัน",
  ui_story_5031_50310101_77_dialog_content = "แต่ฉันไม่เคยคิดเลยนะว่าเมืองนี้จะเจริญขึ้นมาได้ขนาดนี้ เจ้าเมืองที่นี่ต้องเป็นผู้นำที่ฉลาดมากแน่ ๆ",
  ui_story_5031_50310101_78_dialog_content = "<size=33>เจอตัวแล้ว...</size>",
  ui_story_5031_50310101_79_dialog_content = "เธอคิดว่าเขาจะมีอะไรเหมือนกับลอร์ดชวาตส์บ้างไหม?",
  ui_story_5031_50310101_80_dialog_content = "เห็นทุกคนสีหน้ามีความสุขแบบนี้... ทำให้ฉันอยากรู้จริง ๆ นะว่าคนที่มีอำนาจสั่งการที่นี่เป็นคนแบบไหน",
  ui_story_5031_50310101_81_dialog_content = "ฉัน... ฉันว่าเขาไม่เหมือนท่านพ่อหรอก",
  ui_story_5031_50310101_82_dialog_content = "ตามมารยาทแล้ว เราควรไปพบเจ้าเมืองซะก่อน ไหน ๆ ก็มาถึงนี่กันแล้ว",
  ui_story_5031_50310101_83_dialog_content = "เมื่อกี๊ฉันเห็นโปสเตอร์อยู่ริมถนน มีละครสัตว์กับคาร์นิวัลหรืออะไรนี่แหละ จัดการแสดงอยู่บนเรือเดินสมุทรลำใหญ่ ๆ มั้ง?",
  ui_story_5031_50310101_84_dialog_content = "เรื่องนั้นเราไปถามเจ้าเมืองด้วยก็ได้เหมือนกัน",
  ui_story_5031_50310101_85_dialog_content = "ถ้าเรามาที่นี่เพื่อผ่อนคลาย แบบนี้ก็เป็นวิธีเริ่มต้นที่ดีนะ! ประสบการณ์ \"พักผ่อนฤดูร้อน\" ของจริง!",
  ui_story_5031_50310101_86_dialog_content = "ช่าย! ถ้าเป็นฉันคงถามด้วยเหมือนนะว่าที่เมืองฮาร์เบอร์นี่มีอะไรให้ทำอีกบ้าง! หรือว่ามีขนมอะไรอร่อย ๆ ให้กินบ้าง!",
  ui_story_5031_50310101_87_dialog_content = "ไวซ์แทบเก็บความตื่นเต้นไว้ไม่อยู่เลยนะ... สงสัยเราจะไม่ได้หยุดพักกันนานแล้วจริง ๆ",
  ui_story_5031_50310101_88_dialog_content = "<size=33>ล็อกเป้าหมาย...PlayerName!</size>",
  ui_story_5031_50310101_89_dialog_content = "อ้าว แล้วรออะไรกันล่ะ? ไปเลยยย...<size=50>โอ๊ย!</size>",
  ui_story_5031_50310101_90_dialog_content = "โอ๊ย โอ๊ย! หลังฉัน!",
  ui_story_5031_50310101_91_dialog_content = "(เดี๋ยวนะ ทำไมนี่มันคุ้นมากเลย...)",
  ui_story_5031_50310101_92_dialog_content = "ถอยไปนะ ไม่งั้นฉันเรียกให้คนช่วยจริง ๆ ด้วย! ฉันเอาจริงนะ!",
  ui_story_5031_50310101_93_dialog_content = "ไป—",
  ui_story_5031_50310101_94_option_content = "บังคับเชื่อมกระแส... โอ๊ย!!",
  ui_story_5031_50310101_95_dialog_content = "หลังฉัน!!",
  ui_story_5031_50310101_96_dialog_content = "โล โล โล!",
  ui_story_5031_50310101_97_dialog_content = "ดีมาก ไคโล เอาล่ะ หนีทางป่าตามแผน!",
  ui_story_5031_50310101_98_dialog_content = "แต่ฉันแค่... คือ ฉันแค่อยากมีเพื่อนเท่านั้นเอง",
  ui_story_5031_50310101_99_dialog_content = "โล...",
  ui_story_5031_50310101_100_dialog_content = "ใคร ๆ ก็บอกว่าฉันผูกมิตรได้กับสัตว์มหัศจรรย์เท่านั้น ฉันแค่อยากพิสูจน์ตัวเองนั่นไม่ใช่ความจริง และฉันก็ผูกมิตรกับออโรเรียนและเคเลสไทต์ได้เหมือนกัน...",
  ui_story_5031_50310101_101_dialog_content = "ฮิฮิ... นี่ PlayerName นายเป็นเพื่อนคนแรกของฉันเลยนะ!",
  ui_story_5031_50310101_102_dialog_content = "ฉันดีใจนะที่คุณเป็นเพื่อนกับฉัน PlayerName!",
  ui_story_5031_50310101_103_dialog_content = "เห็นไหม อาจารย์! ฉันมีเพื่อนแล้ว!",
  ui_story_5031_50310101_104_dialog_content = "ธะ-เธอจริง ๆ เหรอเนี่ย ฟีญ่า!!",
  ui_story_5031_50310101_105_dialog_content = "แล้วเธอโจมตีฉันที่ถังขยะตรงโน้นทำไมกัน?!",
  ui_story_5031_50310101_106_dialog_content = "ฮิฮิ! เสร็จฉันแล้ว PlayerName!",
  ui_story_5031_50310101_107_dialog_content = "ฟีญ่า?",
  ui_story_5031_50310101_108_dialog_content = "ใช่แล้ว เธอชื่อฟีญ่า อย่าไปสนใจเธอเลย ปกติเธอก็เป็นแบบนี้แหละ",
  ui_story_5031_50310101_109_dialog_content = "นี่น่ะเหรอนักสัตว์มหัศจรรย์วิทยาตัวน้อยที่นายไปเจอเข้าก่อนหน้านี้?",
  ui_story_5031_50310101_110_dialog_content = "ฉันเคยได้ยินเรื่องของกลุ่มคนที่ศึกษาศาสตร์พวกนี้อยู่นะ แต่ไม่นึกเลยว่าจะเจอกับคนที่เด็กขนาดนี้",
  ui_story_5031_50310101_111_dialog_content = "ไม่เจอกันนานเลยนะฟีญ่า",
  ui_story_5031_50310101_112_dialog_content = "อ้าว ไวซ์! ไม่เจอกันนานเลย!",
  ui_story_5031_50310101_113_dialog_content = "ขออนุญาตแนะนำตัวนะ คุณคาร์ลีน ฉันชื่อฟีญ่า และฉันคือนักสัตว์มหัศจรรย์วิทยาหมายเลขหนึ่งของโลกนี้!",
  ui_story_5031_50310101_114_dialog_content = "หรืออย่างน้อยก็ในสักวันแหละนะ ฉันเพิ่งฝึกงานเสร็จ ดังนั้นฉันยังมีช่องให้พัฒนาได้อีกมาก ถ้าฉันสร้างปัญหาอะไรให้คุณในอนาคต รบกวนช่วยอดทนกับฉันด้วยนะคะ!",
  ui_story_5031_50310101_115_dialog_content = "ยินดีที่ได้รู้จักนะ ฉันชื่อคาร์ลีน มาจากลูโมโพลิส รู้ไหม เธอทำให้ฉันนึกถึงราฟาเอลมาก ๆ เลย",
  ui_story_5031_50310101_116_dialog_content = "ฉันควรแนะนำให้เธอรู้จักเมื่อมีโอกาส ฉันว่าเธอสองคนต้องเข้ากันได้ดีทีเดียว",
  ui_story_5031_50310101_117_dialog_content = "เดี๋ยวก่อนนะ...",
  ui_story_5031_50310101_118_dialog_content = "ทำไมถึงทำตัวน่ารักไร้เดียงสาขึ้นมาดื้อ ๆ แบบนี้ล่ะ?",
  ui_story_5031_50310101_119_dialog_content = "พะ-พูดอะไรอย่างนั้น PlayerName? ฉันก็อ่อนหวานแบบนี้เป็นปกติไม่ใช่เหรอ? พูดจาแบบนั้นไม่น่ารักเลยนะรู้ไหม!",
  ui_story_5031_50310101_120_dialog_content = "คงใช่แหละแหม... มาดูกันนะฟีญ่าว่ารอบนี้จะฝืนไปได้ซักเท่าไหร่",
  ui_story_5031_50310101_121_dialog_content = "ว่าแต่เธอมาทำอะไรที่นี่ตั้งแต่แรก? แล้วไคโลอยู่ที่ไหนล่ะ?",
  ui_story_5031_50310101_122_dialog_content = "จุ๊ ๆ! อย่าเสียงดังไป! ถ้าอยากรู้นักละก็ ฉันกับไคโลทำ<color=#FFB400>ภารกิจลับ</color>กันอยู่ อาจารย์สั่งมา!",
  ui_story_5031_50310101_123_dialog_content = "ตอนนี้ไคโลกำลังตรวจสอบน่านน้ำแถบนี้อยู่!",
  ui_story_5031_50310101_124_dialog_content = "\"ภารกิจลับ\" เหรอ? เขาไม่ได้ส่งเธอมาทำภารกิจรบกวนชาวบ้านอีกใช่ไหมเนี่ย?",
  ui_story_5031_50310101_125_dialog_content = "อีกอย่าง... ไคโลนี่ตัวใหญ่มากเลยนะคราวก่อนที่ฉันเจอพวกเธอ! ไม่คิดว่ามันจะเตะตาคนอื่นเหรอ?",
  ui_story_5031_50310101_126_dialog_content = "ฮ่า! นั่นคือร่างใหญ่ของมัน! แต่หลังจากนั้นไคโลก็ฝึกวิชาแปลงร่างจนเก่งแล้วรู้มั้ย?",
  ui_story_5031_50310101_127_dialog_content = "อาจารย์บอกว่าถ้าฝึกฝนมากพอ... มันอาจแปลงร่างเป็นมนุษย์ได้เลยนะ!",
  ui_story_5031_50310101_128_dialog_content = "นั่น... ฟังดูน่ากลัวมากเลยนะ พูดตรง ๆ",
  ui_story_5031_50310101_129_dialog_content = "อย่าได้กลัวไป! มันไม่มีอะไรน่ากลัวเลย ตราบใดที่นายไม่ทำให้ไคโลโกรธ!",
  ui_story_5031_50310101_130_dialog_content = "แต่เรื่องไคโลนี่พอก่อน! ภารกิจในมือตอนนี้สำคัญมาก และต้องใช้สัตว์มหัศจรรย์<color=#FFB400>สายพันธุ์ล้ำค่า</color>!",
  ui_story_5031_50310101_131_dialog_content = "เอิ่ม... ฉันไม่ได้ตั้งใจจะแอบฟังนะ แต่ยังไงก็เถอะ...",
  ui_story_5031_50310101_132_dialog_content = "เธอไม่คิดเหรอว่าควรเบาเสียงลงกว่านี้หน่อย ฟีญ่า?",
  ui_story_5031_50310101_133_dialog_content = "อีกอย่างนะ ที่เธอตามหา PlayerName นี่ก็เพราะจะชวนเขาไปทำ \"ภารกิจลับ\" ของเธอใช่มั้ย?",
  ui_story_5031_50310101_134_dialog_content = "อุ๊ย! สงสัยฉันเสียงดังเกินใช่ไหมเนี่ย?",
  ui_story_5031_50310101_135_dialog_content = "เอาล่ะ ไหน ๆ คุณสองคนก็เป็นเพื่อนสนิทกับ PlayerName ฉันว่าฉันคงไว้ใจให้พวกคุณรู้รายละเอียดได้ล่ะนะ",
  ui_story_5031_50310101_136_dialog_content = "ทีนี้ขอฉันอธิบายสถานการณ์ให้ฟังอย่างละเอียดที่สุดก่อนนะ",
  ui_story_5031_50310101_137_dialog_content = "เรื่องมันเริ่มขึ้นเมื่อสองสามวันก่อน...",
  ui_story_5031_50310101_138_dialog_content = "อะไรรรรรรรนะ! เมืองฮาร์เบอร์? จริงเหรอ?!",
  ui_story_5031_50310101_139_dialog_content = "อะหือ! ที่นั่นวิวสวยสุด ๆ เลยไม่ใช่เหรอ แล้วก็มีอาหารอร่อย ๆ เพียบเลยด้วย!",
  ui_story_5031_50310101_140_dialog_content = "ไม่เห็นรู้เลยว่าอาจารย์สนใจอะไรพวกนี้ด้วย! ถึงกับส่งฉันมาพักร้อนหลังจากที่ทำงานมาอย่างหนักเนี่ย...",
  ui_story_5031_50310101_141_dialog_content = "ชายหาดที่นี่ก็โด่งดังไม่เบานะ พอฉันมานึกดูแล้ว ฉันต้องไปเลือกซื้อชุดว่ายน้ำซะแล้ว!",
  ui_story_5031_50310101_142_dialog_content = "เธอนี่ตื่นเต้นเกินเบอร์ไปมากเลยนะ รู้ตัวไหม...",
  ui_story_5031_50310101_143_dialog_content = "ถ้ามันเป็นทริปที่ดีขนาดนั้นจริง ๆ ฉันคงจัดกระเป๋าเสร็จไปนานแล้ว",
  ui_story_5031_50310101_144_dialog_content = "ฉันจะส่งเธอไปทำงาน ฟีญ่า ไม่ได้ให้ไปพักร้อน",
  ui_story_5031_50310101_145_dialog_content = "นี่เงินค่าเดินทาง ไปได้แล้ว",
  ui_story_5031_50310101_146_dialog_content = "อ้าว! เศษเหรียญแค่นี้ฉันจะเอาไปทำอะไรได้เนี่ย?!",
  ui_story_5031_50310101_147_dialog_content = "ดะ-เดี๋ยวก่อน อาจารย์! อาจารย์จะไปไหนล่ะ?!",
  ui_story_5031_50310101_148_dialog_content = "ฮึ่มมม... ฉันน่าจะรู้ดีนะ! อาจารย์ผู้ไร้ประโยชน์ของฉันไม่เคยจะใจดีขนาดนั้นสักหน่อย!",
  ui_story_5031_50310101_149_dialog_content = "เอ่อ... นี่เธอจะเข้าเรื่องได้รึยัง ฟีญ่า? ฉันว่าเราฟังเรื่องอาจารย์ของเธอมาเยอะแล้วนะ...",
  ui_story_5031_50310101_150_dialog_content = "ก็เนี่ย ฉันกำลังจะเข้าเรื่อง!",
  ui_story_5031_50310101_151_dialog_content = "อะแฮ่ม... วัตถุประสงค์ภารกิจของเราก็คือสัตว์มหัศจรรย์<color=#FFB400>วาฬเมฆา</color>",
  ui_story_5031_50310101_152_dialog_content = "อาจารย์ของฉันติดตามลูมินาชนิดพิเศษของมันมาพักหนึ่งแล้ว มีสัญญาณระบุว่ามันเข้ามาในน่านน้ำของเมืองฮาร์เบอร์",
  ui_story_5031_50310101_153_dialog_content = "แต่หลังจากที่เรามาถึง จู่ ๆ ลูมินาก็หายวับไป...",
  ui_story_5031_50310101_154_dialog_content = "ทฤษฎีของฉันมีอยู่ว่า เนื่องจากมันหายไปดื้อ ๆ หายเกลี้ยงแบบทันทีทันใด เจ้าวาฬเมฆาต้องไม่ได้ไปจากเมืองฮาร์เบอร์แน่นอน... แต่มีอะไรเกิดขึ้นกับมันมากกว่า!",
  ui_story_5031_50310101_155_dialog_content = "เข้าใจแล้ว... เป็นเรื่องน่ากังวลจริง ๆ นั่นแหละ",
  ui_story_5031_50310101_156_dialog_content = "ก็ใช่น่ะสิ แล้วยังไม่หมดนะ... อาจารย์ฉันบอกว่าพลังของวาฬเมฆาตัวนี้แข็งแกร่งกว่าเดรโก้ไลออนซะอีก",
  ui_story_5031_50310101_157_dialog_content = "ตำนานกล่าวว่าพลังของมันทำให้อิคลิพไซท์พากันหวาดกลัว และลูมินาของมันสามารถสลายพลังความมืดที่หนาแน่นสุด ๆ ได้ด้วย",
  ui_story_5031_50310101_158_dialog_content = "ว่ากันว่าวาฬเมฆาตัวนี้มีชีวิตยืนยาวมากเลยด้วยนะ ดังนั้นเป็นไปได้ยากมากที่มันจะตายเองตามธรรมชาติ",
  ui_story_5031_50310101_159_dialog_content = "พอพิจารณาทั้งหมดนี่แล้ว อาจารย์ฉันก็เลยกลัวว่ามันจะตกไปอยู่ในมือคนไม่ดีเข้า",
  ui_story_5031_50310101_160_dialog_content = "วาฬเมฆาเป็นสัตว์ที่มีนิสัยเชื่อง แต่ถ้ามีคนไม่ดีนำพลังของมันไปใช้ในทางที่ผิดแล้ว ผลลัพธ์อาจหายนะได้...",
  ui_story_5031_50310101_161_dialog_content = "ถ้าทุกอย่างเป็นตามที่เธอว่า... งั้นเราก็มัวนิ่งเฉยกันไม่ได้",
  ui_story_5031_50310101_162_dialog_content = "เธอพอรู้บ้างไหมว่ามันอยู่แถวไหน?",
  ui_story_5031_50310101_163_dialog_content = "อืมม... ไม่รู้เลยสักนิด! หลังจากที่อาจารย์โยนงานมาให้ฉัน เขาก็จากไปโดยไม่พูดอะไรเลยสักคำ...",
  ui_story_5031_50310101_164_dialog_content = "แปลว่านี่เธอเตร็ดเตร่อยู่ในเมืองฮาร์เบอร์อย่างไร้จุดหมายตลอดมา จนกระทั่งได้เบาะแสฉันเนี่ยเหรอ? แล้วก็มาซุ่มโจมตีฉันที่นี่เนี่ยนะ?",
  ui_story_5031_50310101_165_dialog_content = "ถูกเผ็งตรงประเด็นไม่ต้องสืบต่อเลย PlayerName! ไม่ใช่แค่นั้นนะ แต่เงินที่อาจารย์ให้ฉันมาเป็นค่าเดินทางก็ใช้หมดไปแล้วด้วย...",
  ui_story_5031_50310101_166_dialog_content = "ฉันคงไม่รู้ว่าจะทำยังไงถ้านายไม่โผล่มา PlayerName!",
  ui_story_5031_50310101_167_dialog_content = "ว่าแล้วเชียว",
  ui_story_5031_50310101_168_dialog_content = "เรารวบรวมข้อมูลกันก่อนดีไหม? นี่เรากำลังจะไปพบเจ้าเมืองอยู่พอดี",
  ui_story_5031_50310101_169_dialog_content = "เขาอาจพอรู้เรื่องนี้อยู่บ้างก็ได้",
  ui_story_5031_50310101_170_dialog_content = "ตกลง! ฉันจะเชื่อคาร์ลีนนะ ไปกันเถอะ!",
  ui_story_5031_50310101_171_dialog_content = "เอ๊ย! นำหน้าไปได้ยังไง ฟีญ่า? เธอรู้เหรอว่าต้องไปทางไหน?",
  ui_story_5031_50310101_172_dialog_content = "นี่องค์ลงจริง ๆ ใช่ไหมเนี่ย?",
  ui_story_5031_50310201_1_dialog_content = "เจ้าเมือง<color=#FFB400>เอลวิส</color> ทหารผู้ภักดีต่อท่านพร้อมแล้ว",
  ui_story_5031_50310201_2_dialog_content = "ทุกอย่างเป็นไปตามแผนครับท่าน เราจะใช้การขนส่งเสบียงกับดอกไม้ไฟไปยังเรือมรกตเป็นฉากหน้า",
  ui_story_5031_50310201_3_dialog_content = "อื้อ เข้าใจแล้ว",
  ui_story_5031_50310201_4_dialog_content = "เรียบร้อย กัปตันพาทู เจ้าคงเป็นคนเดียวที่ข้าไว้ใจได้จริง ๆ ในคราวนี้...",
  ui_story_5031_50310201_5_dialog_content = "ถูกต้องครับท่าน โปรดยกที่เหลือให้ผมจัดการเอง เป็นเกียรติอย่างยิ่งที่ได้รับใช้ท่านเจ้าเมืองครับ",
  ui_story_5031_50310201_6_dialog_content = "ให้ตายสิ... ถ้ามีเวลาให้รอได้อีกนิด ข้าคงไม่ต้องให้เจ้าไปเสี่ยงขนาดนั้น",
  ui_story_5031_50310201_7_dialog_content = "เจ้าเมืองเอลวิส! กัปตันพาทู! ขะ-ขอโทษที่เข้ามารบกวนขอรับ!",
  ui_story_5031_50310201_8_dialog_content = "เสียมารยาทนัก... ฉันบอกไปชัดเจนแล้วนะว่าห้ามใครเข้ามาที่นี่?",
  ui_story_5031_50310201_9_dialog_content = "ชะ-ใช่แล้ว หัวหน้า ได้โปรดอภัยให้ผมด้วย แต่มีขุนนางท่านหนึ่งมาขอพบ...",
  ui_story_5031_50310201_10_dialog_content = "ขุนนางอะไร? พูดจาให้รู้เรื่องซิ! แกเป็นทหารรับใช้ตระกูลโมดาลี ทำตัวให้สมฐานะหน่อย!",
  ui_story_5031_50310201_11_dialog_content = "รับทราบขอรับ! ทะ-ท่านหญิงคาร์ลีน เจ้าหญิงแห่งลูโมโพลิสขอรับ!",
  ui_story_5031_50310201_12_dialog_content = "อะไรนะ? เจ้าหญิงคาร์ลีนแห่งลูโมโพลิสเหรอ?",
  ui_story_5031_50310201_13_dialog_content = "ตามที่คาร์ลีนบอกก็คือ เมืองฮาร์เบอร์เข้ามาอยู่ภายใต้การปกครองและการคุ้มกันของลูโมโพลิสก่อนจะเกิดวิกฤตดาร์กโอเวอร์พอดี",
  ui_story_5031_50310201_14_dialog_content = "แปลว่าก่อนหน้านั้นพวกเขาใช้กองกำลังของตัวเองปกป้องดินแดนเหรอ?",
  ui_story_5031_50310201_15_dialog_content = "เอกสารทางประวัติศาสตร์ระบุว่าครั้งหนึ่งเมืองฮาร์เบอร์เคยเต็มไปด้วยอิคลิพไซท์ พลเมืองที่น่าสงสารต้องต่อสู้หามรุ่งหามค่ำเพื่อปกป้องเมืองไม่ให้ตกสู่หายนะ",
  ui_story_5031_50310201_16_dialog_content = "ตลอดการต่อสู้ที่ยาวนาน กลุ่มผู้ปกครองจากตระกูล<color=#FFB400>โมดาลี</color> ซึ่งมีลูมินามหาศาล ได้ร่วมพันธมิตรกับตระกูลอื่น ๆ ที่ทรงอำนาจ",
  ui_story_5031_50310201_17_dialog_content = "หลังจากต่อสู้นองเลือดกันนับครั้งไม่ถ้วน ในที่สุดพวกเขาก็สามารถขับไล่ผู้รุกรานไปได้จนหมดสิ้น",
  ui_story_5031_50310201_18_dialog_content = "จากนั้น...",
  ui_story_5031_50310201_19_dialog_content = "ด้วยพรจาก<color=#FFB400>เทพเจ้าแห่งแสงสว่าง</color> เมืองนี้ก็แทบไม่มีอิคลิพไซท์มารบกวนอีกเลยนับจากนั้นมา",
  ui_story_5031_50310201_20_dialog_content = "ตอนนี้ประชาชนใช้ชีวิตกันอย่างสงบสุข และเศรษฐกิจก็เฟื่องฟูขึ้นอย่างมาก",
  ui_story_5031_50310201_21_dialog_content = "ข้ารู้สึกเป็นเกียรติมากที่ท่านทราบประวัติของเมืองฮาร์เบอร์เป็นอย่างดี องค์หญิง",
  ui_story_5031_50310201_22_dialog_content = "ข้าซาบซึ้งที่ท่านกับลูโมโพลิสได้ให้การคุ้มครองเราอย่างดี เพราะยังไงเราก็คงรอดจากวิกฤตดาร์กโอเวอร์มาไม่ได้ถ้าต้องพึ่งพา<color=#FFB400>พรจากเทพเจ้าแห่งแสงสว่าง</color>เพียงอย่างเดียว",
  ui_story_5031_50310201_23_dialog_content = "ข้าเอลวิส โมดาลี ทายาทตระกูลโมดาลี และเจ้าเมืองผู้ปกครองเมืองฮาร์เบอร์",
  ui_story_5031_50310201_24_dialog_content = "(แปลกแฮะ... ทำไมลูมินารอบตัวผู้ชายคนนี้ถึงได้จางนัก?)",
  ui_story_5031_50310201_25_dialog_content = "สวัสดี ท่านเจ้าเมืองเอลวิส หวังว่าการมาเยือนของเราคงไม่สร้างความลำบากให้ท่านมากนัก",
  ui_story_5031_50310201_26_dialog_content = "ไม่อยู่แล้ว องค์หญิง ข้าเพียงแค่หวังว่าเจ้าจะแจ้งมาเร็วกว่านี้ ข้าจะได้ต้อนรับท่านกับสหายได้อย่างเหมาะสม",
  ui_story_5031_50310201_27_dialog_content = "เรื่องนั้นไม่จำเป็นหรอก เพราะเราหวังว่าจะได้พบท่านโดยไม่ต้องป่าวประกาศหรือมีพิธีการอะไรมากมาย ขอได้อย่าจัดแจงอะไรให้เป็นพิเศษเลย",
  ui_story_5031_50310201_28_dialog_content = "เพราะยังไงแล้ว ที่เรามายังเมืองฮาร์เบอร์นี่ ก็ไม่ได้เป็นตัวแทนจากไหน แต่เป็นแค่นักท่องเที่ยวมาพักผ่อนช่วงวันหยุดเฉย ๆ",
  ui_story_5031_50310201_29_dialog_content = "วางใจได้เลยองค์หญิง ข้าเข้าใจความต้องการของท่านดี ข้าสันนิษฐานถูกต้องไหมว่าสหายสองคนของท่านไม่ใช่ใครอื่น นอกจากคุณไวซ์กับเคเลสไทต์ในตำนาน?",
