  ui_story_5031_50310201_31_dialog_content = "ส่วนฉันไวซ์ค่ะ เจ้าเมืองเอลวิส แต่ฉันไม่เคยคิดเลยว่านอกจาก PlayerName แล้ว ท่านยังรู้จักฉันอีก",
  ui_story_5031_50310201_32_dialog_content = "อะ-แฮ่ม...!",
  ui_story_5031_50310201_33_dialog_content = "อ้าว? แล้วนี่ใครกันล่ะเนี่ย?",
  ui_story_5031_50310201_34_dialog_content = "สะ-สวัสดีค่ะ! ฉันชื่อฟีญ่า! ฉันเป็นนักสัตว์มหัศจรรย์วิทยาวิชาชีพ แล้วก็เป็นเพื่อนกับ PlayerName ไวซ์ แล้วก็คาร์ลีนด้วย!",
  ui_story_5031_50310201_35_dialog_content = "นักสัตว์มหัศจรรย์วิทยาเหรอ? หึหึ เข้าใจแล้ว... ยินดีที่ได้รู้จักนะคุณฟีญ่า",
  ui_story_5031_50310201_36_dialog_content = "ข้าเตรียมงานเลี้ยงต้อนรับไว้ให้แล้ว ในฐานะเจ้าเมืองแห่งเมืองฮาร์เบอร์ จะเป็นเกียรติมากถ้าเจ้ามาร่วมรับประทานอาหารด้วยกัน",
  ui_story_5031_50310201_37_dialog_content = "อืมม... ว่าแต่คุณไวซ์สนใจกิจกรรมที่จัดบน<color=#FFB400>เรือมรกต</color>ด้วยหรือเปล่า?",
  ui_story_5031_50310201_38_dialog_content = "ที่จริงแล้วข้าเป็นคนเชิญ<color=#FFB400>คณะละครสัตว์นักมายากลและผู้เฒ่าบิลล์</color>กับเรือมรกตมาที่เมืองฮาร์เบอร์เอง",
  ui_story_5031_50310201_39_dialog_content = "ข้าหวังว่าพวกเขาจะมอบประสบการณ์ไม่รู้ลืมให้ประชาชนของข้าในช่วงฤดูร้อนปีนี้",
  ui_story_5031_50310201_40_dialog_content = "เรือทั้งลำนั่นเป็นของคณะละครสัตว์เหรอเนี่ย? มันดูโรแมนติกดีเหมือนกันนะ...",
  ui_story_5031_50310201_41_dialog_content = "ใช่แล้ว ถ้าเจ้ากับสหายสนใจ ก็สามารถร่วมงานเทศกาลได้ตลอดเลยนะ",
  ui_story_5031_50310201_42_dialog_content = "หัวหน้าคณะละครสัตว์เป็นเพื่อนกับข้ามาตั้งแต่เด็ก ถึงจะไม่ได้เจอกันมานานมากแล้ว แต่เขาก็มีความสามารถและไว้ใจได้อีกด้วย",
  ui_story_5031_50310201_43_dialog_content = "ข้ามั่นใจว่าเขาจะมอบความบันเทิงที่ดีที่สุดให้กับคนทั้งเมืองได้",
  ui_story_5031_50310201_44_dialog_content = "โอ้โห... เรือเดินสมุทร!",
  ui_story_5031_50310201_45_dialog_content = "เอิ่ม ขอโทษนะคะ! รบกวนให้เพื่อนของท่านพาเราชมข้างในเรือสักคนได้ไหมคะ เจ้าเมืองเอลวิส?",
  ui_story_5031_50310201_46_dialog_content = "หืมม?",
  ui_story_5031_50310201_47_dialog_content = "<size=33>ฟีญ่า! ไปขออะไรพิลึกแบบนั้นน่ะ?</size>",
  ui_story_5031_50310201_48_dialog_content = "ฉันเพิ่งนึกได้ว่าไคโลบอกฉันว่ามีเรือแปลก ๆ ลำใหญ่มากมาเทียบท่าอยู่ที่เมืองฮาร์เบอร์เมื่อไม่นานมานี้",
  ui_story_5031_50310201_49_dialog_content = "ถ้าจู่ ๆ วาฬเมฆาหายตัวไป อาจมีคนเอาไปเก็บไว้ในเรือแบบนั้นก็ได้!",
  ui_story_5031_50310201_50_dialog_content = "ต้องขออภัยด้วยนะ แต่ข้าเกรงว่าจะจัดการให้ตามคำร้องขอนี้ไม่ได้",
  ui_story_5031_50310201_51_dialog_content = "เอ่อ... ทำไมล่ะคะ?",
  ui_story_5031_50310201_52_dialog_content = "ข้าเองก็ไม่แน่ใจในรายละเอียดเหมือนกัน แต่นี่เป็นกฎข้อหนึ่งของคณะละครสัตว์น่ะ",
  ui_story_5031_50310201_53_dialog_content = "เมื่อวานนี้ข้าขึ้นเรือไปเพื่อคุยกับ<color=#FFB400>เจโน่</color> หัวหน้าคณะละครสัตว์ เรื่องการจัดเสบียงให้กับคณะนักแสดงของเขา",
  ui_story_5031_50310201_54_dialog_content = "ข้านึกว่าเจโน่จะพาฉันเดินชมห้องต่าง ๆ บนเรือ แต่เขากลับให้ข้าเข้าไปได้แค่ทางเดินเท่านั้นตอนที่คุยธุระกัน",
  ui_story_5031_50310201_55_dialog_content = "ข้าอยากรู้อยากเห็น ก็เลยเอ่ยปากว่าอยากดูข้างในเรือลำใหญ่ที่น่าทึ่งแบบนั้น...",
  ui_story_5031_50310201_56_dialog_content = "แต่เขาปฏิเสธข้า บอกว่าเป็นนโยบายของพวกเขาที่อนุญาตให้สมาชิกคณะละครสัตว์เท่านั้นเข้าไปด้านในได้",
  ui_story_5031_50310201_57_dialog_content = "ในฐานะเพื่อนและคู่ค้าทางธุรกิจ ข้าก็เข้าไปได้แค่นั้นเหมือนกัน เกรงว่าคงเป็นไปไม่ได้เลยที่เจ้าจะได้เข้าไปดูมากกว่านั้น",
  ui_story_5031_50310201_58_dialog_content = "มีเหตุผลอะไรเป็นพิเศษไหมที่ทำให้เจ้าอยากเข้าไปข้างในเรือลำนั้น? บางทีข้าอาจเจรจากับหัวหน้าคณะละครสัตว์ให้เจ้าได้นะ",
  ui_story_5031_50310201_59_dialog_content = "ที่จริงแล้ว ฟีญ่าเขา...",
  ui_story_5031_50310201_60_dialog_content = "ฮ่าฮ่าฮ่า! ฉันก็อยากรู้อยากเห็นเหมือนกันนั่นแหละค่ะ! ฉันมาจากเมืองที่เล็กนิดเดียว แล้วก็ไม่เคยเห็นมาก่อนว่าข้างในเรือใหญ่ ๆ มันเป็นยังไง",
  ui_story_5031_50310201_61_dialog_content = "<size=33>อย่าลืมสิ นี่เราทำภารกิจลับกันอยู่นะ! อย่าเปิดเผยข้อมูลสัตว์สายพันธุ์ล้ำค่ามั่วซั่วสิ!</size>",
  ui_story_5031_50310201_62_dialog_content = "ข้าเข้าใจความรู้สึกของเจ้านะ คุณฟีญ่า เพราะยังไงเรือลำใหญ่ ๆ แบบเรือมรกตนี่ก็ไม่ได้หาดูง่าย ๆ แม้แต่ที่เมืองฮาร์เบอร์ก็เถอะ",
  ui_story_5031_50310201_63_dialog_content = "ข้ามั่นใจว่าไม่ใช่เจ้าคนเดียวด้วยนะ คนที่เที่ยวชมงานคาร์นิวัลก็คงอยากรู้อยากเห็นจะแย่แล้วเหมือนกันว่าข้างในมีอะไรอยู่บ้าง",
  ui_story_5031_50310201_64_dialog_content = "ยังไงก็... ให้ข้าลองคุยกับเจโน่ดูอีกทีนะ",
  ui_story_5031_50310201_65_dialog_content = "จริงเหรอคะ? ขอบคุณมากเลยนะคะท่าน!",
  ui_story_5031_50310201_66_dialog_content = "ด้วยความยินดี แต่พยายามอย่าหวังอะไรมากนะ เจโน่ปฏิเสธได้เร็วมาก แม้กับผู้สนับสนุนของเขาก็ตาม",
  ui_story_5031_50310201_67_dialog_content = "แต่ยังไงก็มีกิจกรรมในงานเทศกาลมากมายให้เข้าร่วมบนดาดฟ้าเรือนะ อย่างเช่นประกวดทำอาหาร คาร์นิวัล แล้วก็การแสดงละครสัตว์",
  ui_story_5031_50310201_68_dialog_content = "ข้าเชื่อว่าพวกนั้นก็จะสนองความอยากรู้อยากเห็นของเจ้าได้เหมือนกัน คุณฟีญ่า",
