  ui_story_5031_50310201_75_dialog_content = "นับเป็นเกียรติของข้า องค์หญิง ข้าหวังว่าปัญหาสุขภาพชั่วครู่ของข้าจะไม่ทำให้ท่านหมดสนุกนะ",
