  ui_story_5031_50310201_77_dialog_content = "เดี๋ยวสักพักเราจะไปที่เรือมรกตกันเพื่อเที่ยวชมงานคาร์นิวัล ไม่ต้องลุกไปส่งหรอกค่ะ เดี๋ยวเราไปกันเอง",
