  ui_story_5031_50310201_84_dialog_content = "สั่งให้คนของเราเตรียมตัวไว้นะพาทู",
  ui_story_5031_50310201_85_dialog_content = "เป็น... เป็นไปได้หรือขอรับว่าลูโมโพลิสจะรู้ทันเราเร็วขนาดนี้?",
  ui_story_5031_50310201_86_dialog_content = "ข้าเชื่อว่ายังเร็วเกินไปที่จะบอกได้แน่ชัด... แต่ตอนนี้เราต้องจับตาดูพวกเขาไว้",
  ui_story_5031_50310201_87_dialog_content = "ไม่ว่าจะเกิดอะไรขึ้น แผนการต้องดำเนินต่อในวันนี้",
  ui_story_5031_50310201_88_dialog_content = "ขอโทษในความโง่เขลาด้วยนะท่าน แต่ท่านขอให้หัวหน้าคณะละครสัตว์เจโน่ช่วยไม่ง่ายกว่าหรือขอรับ?",
  ui_story_5031_50310201_89_dialog_content = "ยังไงท่านเองก็บอกว่าเป็นเพื่อนกันมาตั้งแต่เด็ก",
  ui_story_5031_50310201_90_dialog_content = "มันไม่ง่ายขนาดนั้นนะพาทู ถึงจะโตมาด้วยกัน แต่ก็ไม่ได้จำเป็นว่าข้าจะไว้ใจเขาได้",
  ui_story_5031_50310201_91_dialog_content = "เพราะยังไงเขาก็ปฏิเสธคำขอของข้าที่จะเข้าไปชมด้านในของเรือโดยไม่ลังเลสักนิด",
  ui_story_5031_50310201_92_dialog_content = "เท่าที่ฉันรู้มาก็คือ ปัจจุบันนี้เขาภักดีกับ<color=#FFB400>ทรู ออเดอร์</color>",
  ui_story_5031_50310201_93_dialog_content = "ถ้าเราเผยวัตถุประสงค์ออกไปด้วยความเลินเล่อ... แผนการทั้งหมดอาจล่มสลายได้ในทันที",
  ui_story_5031_50310201_94_dialog_content = "ณ จุดนี้ ข้าไม่แน่ใจว่าข้าไว้ใจชายผู้นั้น ที่ครั้งหนึ่งฉันเคยเรียกว่า \"เพื่อน\" ได้หรือไม่",
  ui_story_5031_50310201_95_dialog_content = "เข้าใจแล้วขอรับท่าน เดี๋ยวผมจัดการให้ขอรับ",
  ui_story_5031_50310201_96_dialog_content = "ดีมาก ข้าจะตามดูเจโน่ต่อไป เพื่อดูว่าเขายังใช่คนเดิมที่ข้าเคยรู้จักรึเปล่า...",
  ui_story_5031_50310201_97_dialog_content = "เจ้าเมืองเอลวิสท่าทางนิสัยดีนะ ว่าไหม? เขาต้อนรับเราอย่างอบอุ่น แถมยังใจดีทั้งกับไวซ์แล้วก็กับฉันด้วย",
  ui_story_5031_50310201_98_dialog_content = "ใช่ เขาดูใจดีว่าขุนนางบางคนที่เราเคยเจอมาซะอีก เขาไม่มีท่าทางเสแสร้งเหมือนคนพวกนั้นเลย",
  ui_story_5031_50310201_99_dialog_content = "ถูกต้อง ตระกูลโมดาลีแตกต่างจากขุนนางตระกูลอื่นมากทีเดียว พวกเขาปกป้องดูแลประชาชนอย่างดีเยี่ยม แล้วก็มีคนรักใคร่เยอะมาก",
  ui_story_5031_50310201_100_dialog_content = "ในเรื่องการปกครอง ตระกูลนี้ขึ้นชื่อติดอันดับเลยด้วยนะ แต่น่าเสียดาย...",
  ui_story_5031_50310201_101_dialog_content = "อ๋อ... นี่เกี่ยวข้องกับเรื่องที่ลูมินาของเขาอ่อนแอมาก ๆ เลยด้วยใช่ไหม?",
  ui_story_5031_50310201_102_dialog_content = "ดูเหมือนนายก็สังเกตเห็นเหมือนกันใช่ไหม ตอนที่เอลวิสเริ่มไอแบบควบคุมไม่ได้ก่อนหน้านี้... คือเอาเป็นว่ามันไม่ใช่ไข้หวัดทั่วไปก็แล้วกัน",
  ui_story_5031_50310201_103_dialog_content = "แม้แต่แผลเป็นที่ใบหน้าของเขา... โรคที่เขาเป็นอยู่ตอนนี้ คนอื่น ๆ เรียกกันว่า<color=#FFB400>โรคโมดาลี</color>",
  ui_story_5031_50310201_104_dialog_content = "แปลว่าแผลเป็นที่หน้าเขานี่ได้มาเพราะป่วยเหรอ? ให้ฉันทายยังไงก็คงไม่ถูก...",
  ui_story_5031_50310201_105_dialog_content = "ถ้างั้น... มันเป็นโรคที่รุนแรงรึเปล่า?",
  ui_story_5031_50310201_106_dialog_content = "เรื่องโรคนั่น ฉันก็รู้แค่ชื่อของมันนั่นแหละนะ บอกตรง ๆ ฉันแค่รู้มาผ่าน ๆ ตอนที่เรียนประวัติศาสตร์น่ะ",
  ui_story_5031_50310201_107_dialog_content = "พอสงสัยใคร่รู้มากเข้า ฉันก็รีบไปหาดูข้อมูลเรื่องโรคโมดาลี แล้วคนตระกูลนี้ก็หาตัวยากมาก ๆ",
  ui_story_5031_50310201_108_dialog_content = "เรื่องเดียวที่ฉันรู้มาก็คือ โรคนี้ทำให้ลูมินาของผู้ป่วยลดต่ำลงอย่างรวดเร็ว อีกทั้งยังต้องใช้เวลานานกว่าจะฟื้นฟูลูมินาให้กลับสู่ระดับปกติ",
  ui_story_5031_50310201_109_dialog_content = "สำหรับผู้ที่มีลูมินาในระดับสูงกว่าปกติ มันก็ไม่ได้ส่งผลให้อ่อนแรงอะไรมากนัก แต่กับคนอื่นแล้ว... การติดโรคนี้ทำให้ความสามารถในการใช้ชีวิตตามปกติลดลงอย่างรวดเร็วและรุนแรง",
  ui_story_5031_50310201_110_dialog_content = "รายที่เป็นหนัก ๆ โรคนี้อาจทำให้ถึงตายได้เลย",
  ui_story_5031_50310201_111_dialog_content = "มันรุนแรงขนาดนั้นเลยเหรอ?!",
  ui_story_5031_50310201_112_dialog_content = "ใช่... แต่โรคนี้หายากมาก และพบแค่ในเมืองฮาร์เบอร์เท่านั้น ดังนั้นนักวิชาการจึงเชื่อว่ามันอาจเกี่ยวข้องกับภูมิภาคนี้",
  ui_story_5031_50310201_113_dialog_content = "ส่วนประชาชนที่เมืองฮาร์เบอร์น่ะเชื่อกันเต็มที่เลยว่าโรคนี้เป็นสัญลักษณ์แทน<color=#FFB400>สายเลือดวีรชน</color>ของพวกเขา",
  ui_story_5031_50310201_114_dialog_content = "พวกเขาบอกว่าบรรพบุรุษของตัวเอง คือกลุ่มคนที่ต่อสู้ขับไล่อิคลิพไซท์ไปจนหมดในอดีต ได้รับคำสาปนี้เอาไว้อย่างกล้าหาญและเต็มใจ เพื่อประชาชนของพวกเขา",
  ui_story_5031_50310201_115_dialog_content = "ดังนั้นทายาทของพวกเขาจึงมีโอกาสติดโรคนี้ด้วยเช่นกัน",
  ui_story_5031_50310201_116_dialog_content = "โชคดีที่ยอดผู้ป่วยโรคนี้ที่ยืนยันได้ค่อย ๆ ลดลงแล้วในช่วงหลายปีที่ผ่านมา",
  ui_story_5031_50310201_117_dialog_content = "อ๋อ... อย่างนี้นี่เอง เข้าใจแล้ว",
  ui_story_5031_50310201_118_dialog_content = "เธอไม่ต้องแกล้งทำเป็นเข้าใจหมดนั่นก็ได้นะรู้ไหม?",
  ui_story_5031_50310201_119_dialog_content = "ฉะ-ฉันเข้าใจอยู่แล้ว! แค่เพราะว่าฉันอายุน้อย ไม่ได้หมายความว่าฉันโง่นะ!",
  ui_story_5031_50310201_120_dialog_content = "ยังไงก็ตามแต่ ฉันว่าเจ้าเมืองน่ะเข้าใจชะตาชีวิตของตัวเองดีกว่าใคร ๆ",
  ui_story_5031_50310201_121_dialog_content = "เหมือนฉันนี่ไง ฉันน่ะเกิดมาเพื่อเป็นนักสัตว์มหัศจรรย์วิทยาที่ยิ่งใหญ่ที่สุดในโลก!",
  ui_story_5031_50310201_122_dialog_content = "สืบทอดเกียรติภูมิของคนในอดีตมาไม่รู้กี่รุ่นต่อกี่รุ่น... ต้องเป็นการแบกรับภาระที่หนักอึ้งแน่เลย",
  ui_story_5031_50310201_123_dialog_content = "ในฐานะคนนอก ฉันไม่คิดว่าเรามีสิทธิ์ไปตัดสินสถานการณ์เลยแม้แต่นิดเดียว",
  ui_story_5031_50310201_124_dialog_content = "ฟีญ่าพูดได้ถูกประเด็นมากเลยนะ",
  ui_story_5031_50310201_125_dialog_content = "ใช่ ๆ แต่ถึงไม่พูดอะไรเลยมันก็สนับสนุนประเด็นนี้ได้เหมือนกันนะ",
  ui_story_5031_50310201_126_dialog_content = "ฮิฮิ! ยังไงก็ตาม เราควรตั้งใจหาทางขึ้นไปบนเรือมรกตแล้วก็ดูรอบ ๆ กันนะ มาเถอะ!",
  ui_story_5031_50310201_127_dialog_content = "รีบช่วยสายพันธุ์ล้ำค่าให้ได้ ทำภารกิจนี้ให้เสร็จ แล้วฉันจะได้เที่ยวเล่นสักที!",
  ui_story_5031_50310201_128_dialog_content = "เดี๋ยวก่อนนะฟีญ่า! ว่าแต่อะไรกันที่ทำให้เธอมั่นใจนักว่าจะได้เข้าไปข้างในเรือมรกต?",
  ui_story_5031_50310201_129_dialog_content = "ฉันก็ต้องใช้เสน่ห์เกินห้ามใจของฉันน่ะสิ ใช่ไหมล่ะ?",
  ui_story_5031_50310201_130_dialog_content = "\"เสน่ห์เกินห้ามใจ\" อะไรกัน... แกล้งทำเป็นสัตว์ตัวเล็ก ๆ ไปคัดตัวเข้าคณะละครสัตว์ยังมีโอกาสซะมากกว่า",
  ui_story_5031_50310201_131_dialog_content = "สะอึก!",
  ui_story_5031_50310201_132_dialog_content = "เมื่อกี๊ล้อกันเล่นใช่ไหม?!",
  ui_story_5031_50310201_133_dialog_content = "มานี่เลย!",
  ui_story_5031_50310201_134_dialog_content = "อะ-เอ๊ย เจ็บนะ! อย่าดึงแรง ๆ สิฟีญ่า!",
  ui_story_5031_50310201_135_dialog_content = "ลงทะเลไปเลยตาบ้า! เดี๋ยวให้ไคโลจับโยนเล่นให้เหมือนลูกบอลเลย ให้ตายเถอะ!",
  ui_story_5031_50310201_136_dialog_content = "อะไรกัน? นี่หาว่าไคโลเป็นแมวน้ำเหรอ? ฉันว่าไคโลไม่ชอบหรอกนะแบบนั้น!",
  ui_story_5031_50310201_137_dialog_content = "ก็ช่างสิ!",
  ui_story_5031_50310201_138_dialog_content = "เฮ่อ... เห็นพวกนั้นเถียงกันแบบนี้ ฉันกลับสบายใจเฉยเลยแฮะ",
  ui_story_5031_50310201_139_dialog_content = "นั่นสิ... เราไม่ได้ผ่อนคลายกันแบบมาพักนึงแล้วนะ",
  ui_story_5031_50310201_140_dialog_content = "นั่นมัน!",
  ui_story_5031_50310201_141_dialog_content = "โอ๊ย ๆ พอได้แล้ว! มีอะไรเหรอคาร์ลีน?",
  ui_story_5031_50310201_142_dialog_content = "ตรงนั้นน่ะ... อิคลิพไซท์มาทำอะไรกันที่ริมฝั่งทะเล?!",
  ui_story_5031_50310201_143_dialog_content = "เตรียมต่อสู้ได้เลย แล้วก็ระวังตัวด้วยนะทุกคน! อิคลิพไซท์พวกนี้มีอะไรแปลก ๆ...",
  ui_story_5031_50310202_1_dialog_content = "โฮกกก...",
  ui_story_5031_50310202_2_dialog_content = "ทำไมอิคลิพไซท์พวกนี้อ่อนแอจัง...?",
  ui_story_5031_50310202_3_dialog_content = "พวกคุณ ไม่เป็นไรใช่ไหม?",
  ui_story_5031_50310202_4_dialog_content = "เดี๋ยวก่อน... ท-ท่านคือเจ้าหญิงคาร์ลีนนี่นา! ขะ-ขอโทษด้วยถ้าท่านได้รับบาดเจ็บ... เป็นความประมาทของผมเองที่ปล่อยให้อิคลิพไซท์พวกนั้นผ่านเข้ามาได้!",
  ui_story_5031_50310202_5_dialog_content = "ไม่ต้องตกใจไปหรอก เราไม่ใช่ประชาชนทั่วไปที่ไม่มีอาวุธ และพวกเราสามารถปกป้องตัวเองได้เป็นอย่างดี",
  ui_story_5031_50310202_6_dialog_content = "แต่ถึงอย่างนั้น นายกับทหารคนอื่น ๆ ก็ต้องระแวดระวังอยู่ตลอดเวลา อันตรายมันมาถึงตัวได้เสมอ",
  ui_story_5031_50310202_7_dialog_content = "รับทราบ! ขอขอบคุณสำหรับคำแนะนำของท่าน องค์หญิง! เราจะเพิ่มการลาดตระเวน รวมทั้งสืบเสาะที่มาของอิคลิพไซท์พวกนี้!",
  ui_story_5031_50310202_8_dialog_content = "ดีมาก ไปทำงานได้แล้วทหาร",
  ui_story_5031_50310202_9_dialog_content = "รับทราบ องค์หญิง!",
  ui_story_5031_50310202_10_dialog_content = "เจ๋งมากเลยคาร์ลีน! ท่าทางกับน้ำเสียงสมกับเป็นราชินีจริง ๆ!",
  ui_story_5031_50310202_11_dialog_content = "ก็ต้องเหมือนสิฟีญ่า! คาร์ลีนเป็นลูกสาวของเจ้าเมืองลูโมโพลิส แน่นอนว่าเธอต้องเป็นผู้นำที่ฉลาดเฉลียวในสักวัน",
  ui_story_5031_50310202_12_dialog_content = "ขะ-ขอบใจนะ แต่ฉันยังต้องเรียนรู้อีกมากเลย",
  ui_story_5031_50310202_13_dialog_content = "แต่เรื่องนั้นพอก่อนเถอะ เรือมรกตอยู่ข้างหน้านี่เอง รีบไปกันเถอะ",
  ui_story_5031_50310202_14_dialog_content = "ใครอยากแข่งขันปรุงอาหาร มาทางนี้!",
  ui_story_5031_50310202_15_dialog_content = "เราก็มาถึงกันจนได้เนอะ? งานคึกคักดีจัง!",
  ui_story_5031_50310202_16_dialog_content = "มาเริ่มหาข้อมูลกันก่อนดีกว่า PlayerName",
  ui_story_5031_50310202_17_dialog_content = "อื้อ แบบนั้นก็เข้าท่า",
  ui_story_5031_50310202_18_dialog_content = "สวัสดี ถามเรื่องคาร์นิวัลหน่อยได้ไหมครับ...?",
  ui_story_5031_50310202_19_dialog_content = "อ้าว! ยินดีต้อนรับสู่คณะละครสัตว์นักมายากลและผู้เฒ่าบิลล์!",
  ui_story_5031_50310202_20_dialog_content = "ท่าทางเพิ่งเคยมาดูละครสัตว์ของเราครั้งแรกใช่ไหมเนี่ย? ไม่ต้องอายหรอกพวกคุณ! มาทางนี้เลย!",
  ui_story_5031_50310202_21_dialog_content = "ขอแค่อย่าก่อเรื่องบนเรือนี้ก็แล้วกัน ตกลงไหม? ฉันจะไม่ใจดีแบบนี้หรอกนะถ้าพวกคุณเริ่มก่อความวุ่นวายกัน...",
  ui_story_5031_50310202_22_dialog_content = "มาเร็วเมอรีลท์! หัวหน้าเจโน่สั่งให้เรามาต้อนรับแขกตรงนี้นะ อย่าอู้สิ!",
  ui_story_5031_50310202_23_dialog_content = "นั่น ๆ มีคนมาแล้วนั่น สเป็กเธอเลยด้วย! เธอเข้าไปทักทายซะดีไหมเมอรีลท์?",
  ui_story_5031_50310202_24_dialog_content = "เอ๊ย! ซับลี่ อย่าผลักสิ...",
  ui_story_5031_50310202_25_dialog_content = "เอ เขาหน้าเหมือนตาคนนั้นอยู่นะ ว่าไหม? เมอรีลท์ เข้าไปดูใกล้ ๆ เลยสิ!",
  ui_story_5031_50310202_26_dialog_content = "หา? เหมือนใครเหรอ? เธอสองคนพูดเรื่องอะไรกันน่ะ?",
  ui_story_5031_50310202_27_dialog_content = "เขาหน้าเหมือนคนในโปสเตอร์ในอัมบราตันเดลี่ไง! ที่เมอรีลท์เอาไปเก็บไว้ดูเองคนเดียวน่ะ!",
  ui_story_5031_50310202_28_dialog_content = "เอ่อ... นี่พูดถึงอะไรกันแน่?",
  ui_story_5031_50310202_29_dialog_content = "เดี๋ยวนะ ดูเหมือนกันจริง ๆ ด้วย! คุณไม่ได้บังเอิญใช่เคเลสไทต์คนนั้นใช่ไหม?",
  ui_story_5031_50310202_30_dialog_content = "ชะ-ใช่สิ ที่จริงแล้วก็ใช่... แต่พวกเธอสามคนรู้จักฉันได้ยังไงเหรอ?",
  ui_story_5031_50310202_31_dialog_content = "!!",
  ui_story_5031_50310202_32_dialog_content = "ทำไมเมอรีลท์ถึงวิ่งหนีไปล่ะซับลี่?",
  ui_story_5031_50310202_33_dialog_content = "แล้วนี่เราต้องจับตัวเจ้าคนนี้ไว้รึเปล่า?",
  ui_story_5031_50310202_34_dialog_content = "อะ-อะไรกัน?!",
  ui_story_5031_50310202_35_dialog_content = "ฮ่าฮ่าฮ่า สนุกจังเลย! ใจเย็นก่อนนะฟริเม็ต ปล่อยพวกเขาให้เป็นหน้าที่ของเรนโบว์ดีกว่า ตอนนี้ไปตามหาเมอรีลท์ก่อน ตกลงไหม?",
  ui_story_5031_50310202_36_dialog_content = "อ้าว! นี่อู้งานอีกแล้วเหรอ?",
  ui_story_5031_50310202_37_dialog_content = "ขอโทษทีทุกคน! สามคนนั้นแค่มาช่วยงานชั่วคราวน่ะ",
  ui_story_5031_50310202_38_dialog_content = "พวกคุณต้องมาเที่ยวงานคาร์นิวัลกันแน่เลยใช่ไหม?",
  ui_story_5031_50310202_39_dialog_content = "ฉันขอแนะนำตัวเองนะ ฉันชื่อเรนโบว์ ฉันเป็นพิธีกร ผู้ประสานงานลูกค้า หัวหน้าฝ่ายรักษาความปลอดภัย และวิศวกรทางทะเลฝึกหัดประจำคณะละครสัตว์นี้!",
  ui_story_5031_50310202_40_dialog_content = "ยะ-ยาวจัง...",
  ui_story_5031_50310202_41_dialog_content = "ฮิฮิ! ทุกคนถึงได้คิดว่าฉันสุดยอดมากเลยไงล่ะ นึกออกไหม?",
  ui_story_5031_50310202_42_dialog_content = "ยินดีที่ได้รู้จักนะเรนโบว์! ช่วยบอกทีได้ไหมว่าพวกเราจะเข้าไปในเรือได้ยังไงบ้าง ว้าว!",
  ui_story_5031_50310202_43_dialog_content = "นี่จะทำอะไรน่ะ? คิดว่าเธอจะปล่อยให้เข้าไปข้างในแค่เพราะว่าเราขอเข้าไปงั้นเหรอ?",
  ui_story_5031_50310202_44_dialog_content = "มะ-ไม่งั้นเราควรจะต้องทำยังไงล่ะ?",
  ui_story_5031_50310202_45_dialog_content = "สวัสดี เราอยากรู้เรื่องราวของคาร์นิวัลเพิ่มเติมสักหน่อยน่ะ จะได้รู้ว่าเที่ยวชมยังไงถึงจะสนุกที่สุด",
  ui_story_5031_50310202_46_dialog_content = "คืองานคาร์นิวัลเนี่ย ตอนนี้กำลังจัดเตรียมอยู่นะจ๊ะ เดินเล่นบนดาดฟ้าเรือรอทางเราให้สัญญาณไปก่อนก็ได้",
  ui_story_5031_50310202_47_dialog_content = "ตอนนี้ฉันแนะนำให้ทุกคนไปชมการประกวดปรุงอาหารก่อน จัดอยู่ใกล้ ๆ ตรงนี้นี่เอง!",
  ui_story_5031_50310202_48_dialog_content = "การประกวดที่กำลังจะเริ่มขึ้นรอบนี้โหดมากเลยนะ แล้วก็มีแผงอาหารรสเลิศให้แวะชมด้วย!",
  ui_story_5031_50310202_49_dialog_content = "เดินไปทางนั้นได้เลยจ้ะ ยังไงก็หาเจอแน่นอน!",
  ui_story_5031_50310202_50_dialog_content = "ขอบคุณที่สละเวลานะ เดี๋ยวเราจะลองเดินดูรอบ ๆ",
  ui_story_5031_50310202_51_dialog_content = "สมาชิกคณะละครสัตว์เมื่อกี๊ไม่ธรรมดาเลย ว่าไหม?",
  ui_story_5031_50310202_52_dialog_content = "โดยเฉพาะสามพี่น้องนั่น ดูท่าทางสนใจ PlayerName เป็นพิเศษเลย",
  ui_story_5031_50310202_53_dialog_content = "จริงเหรอ...? ฉันว่าฉันไม่ยุ่งกับคนแปลก ๆ จะดีกว่า...",
  ui_story_5031_50310202_54_dialog_content = "ฉันอดคิดไม่ได้ว่าเดี๋ยวนี้ทุกอย่างรอบตัวมันช่างวุ่นวายซะเหลือเกิน ตอนนี้ฉันอยากจะพักผ่อนหย่อนใจมากกว่า",
  ui_story_5031_50310202_55_dialog_content = "อืมม ทำยังไงถึงจะเข้าไปในตัวเรือได้นะเนี่ย?",
  ui_story_5031_50310202_56_dialog_content = "ฉันนึกว่าฉันโน้มน้าวคุณผู้หญิงใจดีคนนั้นได้แล้วซะอีก",
  ui_story_5031_50310202_57_dialog_content = "เธอไม่คิดเหรอว่าถ้าซื่อสัตย์มากเกินไป จะทำให้โดนจับโยนลงทะเลซะมากกว่า?",
  ui_story_5031_50310202_58_dialog_content = "อย่าลืมที่เอลวิสบอกนะ ด้านในของเรือลำนี้เป็นพื้นที่สำหรับสมาชิกคณะละครสัตว์เท่านั้น",
  ui_story_5031_50310202_59_dialog_content = "เราเริ่มสอดส่องดูบนดาดฟ้าเรือนี้ก่อนจะดีที่สุด ใครจะไปรู้... เราอาจพบอะไรบ้างก็ได้",
  ui_story_5031_50310202_60_dialog_content = "เดี๋ยวก่อนนะ... แผงที่อยู่ถัดไปนิดนึงนั่นน่ะ... ฉันเห็นคนหน้าคุ้น ๆ อยู่นะ",
  ui_story_5031_50310202_61_dialog_content = "ผมยินดีนำเสนอหนึ่งในวิธีดับร้อนที่ดีที่สุดในโลก เพื่อรับมือกับฤดูร้อนที่โหดหิน",
  ui_story_5031_50310202_62_dialog_content = "รอบนี้มีรสชาติใหม่ล่าสุด <color=#FFB400>สายลมเมืองฮาร์เบอร์ ลิมิเต็ด</color>",
  ui_story_5031_50310202_63_dialog_content = "ผู้ที่ซื้อน้ำแข็งไสสิบถ้วย จะได้รับกระเป๋าน้ำร้อนรุ่นพิเศษ สลักรูปเคเลสไทต์ผู้น่ารัก!",
  ui_story_5031_50310202_64_dialog_content = "ได้เลยจ้า น้ำแข็งไสสิบถ้วย พร้อมกระเป๋าน้ำร้อนสำหรับสาวสวย",
  ui_story_5031_50310202_65_dialog_content = "ฉันเองต่างหากที่เป็นคนคิดค้นน้ำแข็งไสแบบนี้ขึ้นมา! แล้วฉันก็ไม่เชื่อสายตาเลยด้วยว่าเคลเคนจะเอารูปนายไปใช้กับกระเป๋านั่น!",
  ui_story_5031_50310202_66_dialog_content = "ไวซ์... เธอต้องจำได้สิว่าเธอเซ็นสัญญา \"<color=#FFB400>ส่งต่อความลับทางการค้า</color>\" ให้เคลเคนไปแล้วเมื่อปีก่อน?",
  ui_story_5031_50310202_67_dialog_content = "ฉันเกรงว่านี่แหละคือผลลัพธ์ที่ตามมา",
  ui_story_5031_50310202_68_dialog_content = "โอ๊ะโอ... หวานเกินไปแล้ว",
  ui_story_5031_50310202_69_dialog_content = "มันไม่มีความซับซ้อนเหมือนน้ำแข็งไสของไวซ์เลย",
  ui_story_5031_50310202_70_dialog_content = "ฉะ-ฉันขอถ้วยนึงด้วยสิ!",
  ui_story_5031_50310202_71_dialog_content = "แหม อดใจไม่ไหวใช่ไหมล่ะ?",
  ui_story_5031_50310202_72_dialog_content = "ไวซ์ยังเซ็งเรื่องการโอนทรัพย์สินทางปัญญาอันแสนเศร้าอยู่เลย",
  ui_story_5031_50310202_73_dialog_content = "ฉะ-ฉันไม่ได้ว่าอะไรซะหน่อย... ฉันก็แค่ดีใจ ที่ทุกคนมีโอกาสได้กินน้ำแข็งไสอร่อย ๆ ไม่ว่าเรื่องนั้นจะเกิดขึ้นได้ยังไงก็เหอะ และฉันก็แค่... ฉันแค่อยาก...",
  ui_story_5031_50310202_74_dialog_content = "ฉันจะให้เคลเคนโอนมันกลับมาให้ฉัน!",
  ui_story_5031_50310202_75_dialog_content = "<color=#e8d9bb>หลังจากนั้นไม่นาน</color>",
  ui_story_5031_50310202_76_dialog_content = "ว้าว! หวานเย็นของจริง",
  ui_story_5031_50310202_77_dialog_content = "อย่ากินทีเดียวหมดนะ ไม่งั้นเย็นจี๊ดขึ้นสมองแน่!",
  ui_story_5031_50310202_78_dialog_content = "นี่ไวซ์ยังคุยกับเคลเคนอยู่อีกเหรอ? สองคนนั้นมีอะไรกันรึเปล่า?",
  ui_story_5031_50310202_79_dialog_content = "PlayerName!",
  ui_story_5031_50310202_80_dialog_content = "เอ๋? เสียงใครคุ้น ๆ?",
  ui_story_5031_50310202_81_dialog_content = "PlayerName ไม่อยากเชื่อเลย นายจริง ๆ ด้วย!",
  ui_story_5031_50310202_82_dialog_content = "เฟลอร์ คุณมาทำอะไรที่นี่?",
  ui_story_5031_50310202_83_dialog_content = "อ้าว? นายไม่ได้มาแข่งชิงแชมป์หม้อเวทมนตร์ด้วยหรอกเหรอ? ที่เป็นเทศกาลประกวดอาหารรสเลิศน่ะ น่าจะเริ่มเร็ว ๆ นี้แหละ",
  ui_story_5031_50310202_84_dialog_content = "แล้วฉันก็ต้องขอบคุณนายด้วยนะที่ช่วยเรื่องอบขนมปังคราวก่อนโน้น",
  ui_story_5031_50310202_85_dialog_content = "ฉันมาคิด ๆ ดูแล้ว ก็เลยตัดสินใจเข้าร่วมการแข่งขัน มันเป็นวิธีที่ดีที่สุดแล้วที่จะพัฒนาตัวเองและสร้างสไตล์อันโดดเด่น",
  ui_story_5031_50310202_86_dialog_content = "เอ้อ ยินดี ๆ ต้องบอกเลยนะว่าผมไม่เคยได้ยินเรื่องการแข่งขันประกวดอาหารรสเลิศอะไรนี่จนกระทั่งตอนนี้นี่แหละ มันเรียกว่าอะไรนะ? \"<color=#FFB400>หม้อเวทมนตร์</color>\" เหรอ?",
  ui_story_5031_50310202_87_dialog_content = "เดี๋ยวนะ! เหมือนเชฟกระทะเหล็กแห่งทะเลทรายเรดีเซลนั่นรึเปล่า?",
  ui_story_5031_50310202_88_dialog_content = "คุณลุงจอห์นนี่ ผู้เชี่ยวชาญด้านอิคลิพไซท์น่ะเหรอ? คนเดียวกันนั่นแหละ! มันคือหม้อเวทมนตร์ที่เขาใช้นั่นแหละ!",
  ui_story_5031_50310202_89_dialog_content = "เดี๋ยวนะ \"คุณลุงจอห์นนี่\" ที่ว่านี่ใครกันเหรอคาร์ลีน?",
  ui_story_5031_50310202_90_dialog_content = "น่าจะเป็นคนแต่งตำราอาหารชื่อดังมาก ๆ ที่อาศัยอยู่ในทะเลทรายเรดีเซลน่ะ ฉันเองก็ไม่รู้อะไรกว่านั้นเหมือนกัน",
  ui_story_5031_50310202_91_dialog_content = "แล้วทำไมถึงได้มาชอบทางนี้ล่ะเนี่ย?",
  ui_story_5031_50310202_92_dialog_content = "เขาไม่ใช่คนเขียนตำราอาหารทั่วไปนะ! เขาคิดค้นเมนูอาหารที่โด่งดังไปทั่วทั้งทวีปไม่รู้กี่อย่างในหม้อใบนั้น!",
  ui_story_5031_50310202_93_dialog_content = "ค-คิดว่าคุณลุงจอห์นนี่จะลงแข่งชิงแชมป์เองด้วยรึเปล่า?",
  ui_story_5031_50310202_94_dialog_content = "โอ๊ย ไม่หรอก เชฟอย่างเขามีอะไรดี ๆ ให้ทำมากกว่า... เดี๋ยวนะ นี่เขาเอาหม้ออันโด่งดังของคุณลุงมาเป็นรางวัลด้วยเหรอเนี่ย?",
  ui_story_5031_50310202_95_dialog_content = "ถูกต้องแล้ว! ผู้ชนะรางวัลที่หนึ่งจะได้รับรางวัลใหญ่เป็นหม้อเวทมนตร์ของมาสเตอร์เชฟเองเลย!",
  ui_story_5031_50310202_96_dialog_content = "ฉันไม่รู้เลยสักนิดว่าคุณลุงจะไปร่วมงานด้วยรึเปล่า แต่ฉันมั่นใจว่ารางวัลแบบนี้ต้องดึงดูดความสนใจดาวเด่นจากทั่วโลกได้แน่นอน!",
  ui_story_5031_50310202_97_dialog_content = "ผมก็อยากลงแข่งด้วย! ได้ไหมนะ? พวกนั้นจะให้ผมแข่งไหม?",
  ui_story_5031_50310202_98_dialog_content = "ถ้าเอาหม้อวิเศษใบนั้นให้ไวซ์นะ เราทุกคนบนยานโคลอสซัสต้องได้รับอานิสงส์ไปด้วยแน่นอน!",
  ui_story_5031_50310202_99_dialog_content = "อ๊ะ! มาคึกอะไรเอาตอนนี้ล่ะเนี่ย PlayerName ทำไมจู่ ๆ ก็เสียงดังขึ้นมา?",
  ui_story_5031_50310202_100_dialog_content = "ขอโทษทีนะเฟลอร์ ฉันขอคุยกับ PlayerName เงียบ ๆ นิดนึงสิ",
  ui_story_5031_50310202_101_dialog_content = "อย่าเซ้าซี้มากนักเลยน่า คาร์ลีน ฟีญ่า",
  ui_story_5031_50310202_102_dialog_content = "นี่! เฟลอร์ รอด้วยนะ! เดี๋ยวผมกลับมา!",
  ui_story_5031_50310202_103_dialog_content = "ก็ได้ เดี๋ยวฉันรอ",
  ui_story_5031_50310202_104_dialog_content = "ฉันจะรอนายอยู่ที่นี่นะ PlayerName!",
  ui_story_5031_50310202_105_dialog_content = "PlayerName อย่าเพิ่งคิดการใหญ่เลยดีกว่าไหม?",
  ui_story_5031_50310202_106_dialog_content = "โทษที ฉันว่าเมื่อกี๊ฉันคงตื่นเต้นไปหน่อย",
  ui_story_5031_50310202_107_dialog_content = "นั่นไงล่ะ ฉันว่ามีคนอยากได้หม้อวิเศษนั่นจนตัวสั่นจริง ๆ ซะแล้วสินะ PlayerName",
  ui_story_5031_50310202_108_dialog_content = "มาทำอะไรที่นี่เนี่ย? เจอตัวจนได้!",
  ui_story_5031_50310202_109_dialog_content = "ไวซ์? คุยกับเคลเคนได้ความว่ายังไงบ้าง?",
  ui_story_5031_50310202_110_dialog_content = "ล้มเหลวไม่มีชิ้นดี! สิ่งเดียวที่ปลอบใจฉันได้ก็คือ ฉันได้น้ำแข็งไสฟรีมาให้ทุกคนตั้งสองสามแก้วแน่ะ!",
  ui_story_5031_50310202_111_dialog_content = "กินได้ตามสบายเลยนะเพื่อน ๆ! ให้ขนมหวานเย็นเจี๊ยบพวกนี้ล้างความล้มเหลวออกไปให้สะอาดเอี่ยมเลย! *งั่ม ๆ*",
  ui_story_5031_50310202_112_dialog_content = "ฉันว่าไวซ์ไม่สบอารมณ์จริง ๆ นะเนี่ย... *งั่ม ๆ*",
  ui_story_5031_50310202_113_dialog_content = "อ๊าก ขึ้นสมอง!",
  ui_story_5031_50310202_114_dialog_content = "กินทีเดียวหมดก็เป็นแบบนี้แหละ รู้มั้ย โอ๊ย... ฉันก็เป็นเหมือนกัน",
  ui_story_5031_50310202_115_dialog_content = "เอ๋? เห็นบันไดทางลงตรงนั้นไหม? อย่าบอกนะว่าทางลงไปชั้นล่างอยู่ใกล้แค่นี้มาตั้งแต่แรก?",
  ui_story_5031_50310202_116_dialog_content = "เอ๋? ไหนฉันดูซิ",
  ui_story_5031_50310202_117_dialog_content = "ฉันว่าใช่จริง ๆ ด้วย... ยังไงดี? เราควรลงไปไหม?",
  ui_story_5031_50310202_118_dialog_content = "นี่คิดจะบุกรุกเข้าไปหน้าตาเฉยอีกแล้วเหรอ?",
  ui_story_5031_50310202_119_dialog_content = "ก็ถ้าคิดว่านี่คือคนชั่วที่จับตัววาฬเมฆาไป มันก็คงไม่เอาพรมยินดีต้อนรับมาปูให้หรอกนะ",
  ui_story_5031_50310202_120_dialog_content = "สุดท้ายแล้ว ยังไงเราก็ต้องลองพยายามดู",
  ui_story_5031_50310202_121_dialog_content = "ก๊อก ๆ ขอโทษที่รบกวนนะ ขอเข้าไปหน่อย!",
  ui_story_5031_50310202_122_dialog_content = "นี่เธอพูดว่า \"ก๊อก ๆ\" จริง ๆ น่ะเหรอ?",
  ui_story_5031_50310202_123_dialog_content = "<color=#e8d9bb>เอี๊ยด—</color>",
  ui_story_5031_50310202_124_dialog_content = "อ๊าา!",
  ui_story_5031_50310202_125_dialog_content = "ใครน่ะ?!",
  ui_story_5031_50310202_126_dialog_content = "อ๊ะ ขอโทษที! คณะนักท่องเที่ยวผ่านมาค่ะ!",
  ui_story_5031_50310202_127_dialog_content = "ถ้าพร้อมจะทิ้งความหวังและอนาคตของตัวเองทั้งหมดไป ก็จงก้าวผ่านประตูมา",
  ui_story_5031_50310202_128_dialog_content = "ไม่เช่นนั้นก็ จงออกไปจากที่นี่ซะ",
  ui_story_5031_50310202_129_dialog_content = "หา?",
  ui_story_5031_50310202_130_dialog_content = "ฉันหมายความว่าพื้นที่ชั้นล่าง ห้ามนักท่องเที่ยวเข้า!",
  ui_story_5031_50310202_131_dialog_content = "ช่วยกลับไปได้แล้ว",
  ui_story_5031_50310202_132_dialog_content = "อ๋อ โทษที! เราจะไปเดี๋ยวนี้ล่ะครับ",
  ui_story_5031_50310202_133_dialog_content = "เป็นไงล่ะ... ไม่ได้เดินเข้าไปง่าย ๆ นะ",
  ui_story_5031_50310202_134_dialog_content = "ไม่ง่ายแน่นอน... ไม่ต้องสงสัยเลย",
  ui_story_5031_50310202_135_dialog_content = "<color=#e8d9bb>ปั้ง!</color>",
  ui_story_5031_50310202_136_dialog_content = "\"ท่านผู้โดยสารโปรดทราบ! ขณะนี้การเตรียมงานแข่งขันประจำงานคาร์นิวัลได้เสร็จสิ้นลงแล้ว\"",
  ui_story_5031_50310202_137_dialog_content = "\"ขอให้ผู้เข้าร่วมที่สนใจทั้งหมดกรุณาไปยังบริเวณที่จัดไว้เพื่อสมัครและลงทะเบียนด้วยค่ะ\"",
  ui_story_5031_50310202_138_dialog_content = "\"ผู้เข้าแข่งขันมีโอกาสได้รับรางวัลเป็นไนท์เทียมจำนวนมาก รวมทั้งโอกาสสัมผัสประสบการณ์ชีวิตสมาชิกคณะละครสัตว์ถึงหนึ่งวันเต็ม ๆ\"",
  ui_story_5031_50310202_139_dialog_content = "\"นอกจากนี้ผู้ชนะรางวัลที่หนึ่งจะได้รับรางวัลใหญ่ด้วยตนเองจากมือของท่านหัวหน้าคณะละครสัตว์อีกด้วยนะคะ\"",
  ui_story_5031_50310202_140_dialog_content = "คิดว่าไงล่ะ? ชีวิตสมาชิกคณะละครสัตว์หนึ่งวันเต็ม แปลว่าน่าจะได้ลงไปดูชั้นล่าง ๆ ด้วยนะ",
  ui_story_5031_50310202_141_dialog_content = "ความคิดไม่เลวนะฉันว่า",
  ui_story_5031_50310202_142_dialog_content = "มาเถอะ ไปดูใกล้ ๆ กัน",
  ui_story_5031_50310202_143_dialog_content = "ตายจริง ไม่นึกไม่ฝันมาก่อน คนเต็มไปหมดเลยนะเนี่ย!",
  ui_story_5031_50310202_144_dialog_content = "เฮ้อ... ยังกับฝูงตั๊กแตนรุมตอมแน่ะ",
  ui_story_5031_50310202_145_dialog_content = "เจ้าหน้าที่ตุลาการผู้น่านับถืออย่างฉัน ผู้พิพากษาแมทธิว ทำไมต้องมาเกลือกกลั้วกับพวกสามัญชนต่ำต้อยด้วยเนี่ย?",
  ui_story_5031_50310202_146_dialog_content = "...",
  ui_story_5031_50310202_147_dialog_content = "ไปรบกวนคนอื่นไป๊!",
  ui_story_5031_50310202_148_dialog_content = "เฮ้อ ความสับสนวุ่นวายที่นี่ไม่เหมาะกับอารมณ์ขันที่ละเอียดอ่อนของฉันเลย นี่ฉันเองก็จะหมดความอดทนกับนายแล้วนะโลเว่",
  ui_story_5031_50310202_149_dialog_content = "คาร์ลีน ฉันว่าสองคนนี้มาจากลูโมโพลิสแหละ",
  ui_story_5031_50310202_150_dialog_content = "น่าจะมาจากศาลยุติธรรมมั้ง... ใครจะไปสนใจล่ะ",
  ui_story_5031_50310202_151_dialog_content = "ไวซ์! PlayerName กับคาร์ลีนด้วย! แล้วก็...?",
  ui_story_5031_50310202_152_dialog_content = "เจ้าหน้าที่กรอนรู! นี่...",
  ui_story_5031_50310202_153_dialog_content = "ฉันชื่อฟีญ่าค่ะ เป็นนักสัตว์มหัศจรรย์วิทยา ยินดีที่ได้รู้จักค่ะ!",
  ui_story_5031_50310202_154_dialog_content = "เยี่ยมมาก หวังว่านายจะเป็นตัวอย่างที่ดีให้กับเด็ก ๆ นะเคเลสไทต์?",
  ui_story_5031_50310202_155_dialog_content = "แล้วมามองฉันทำไมเนี่ย?!",
  ui_story_5031_50310202_156_dialog_content = "คุณกรอนรูมาธุระอะไรเหรอคะ?",
  ui_story_5031_50310202_157_dialog_content = "ฉันสังหรณ์ใจเฉย ๆ ว่าการแสดงที่นี่น่าจะสนุกดี แล้วฉันก็มากับเพื่อนร่วมชั้นผู้น่ารักของเธอด้วย",
  ui_story_5031_50310202_158_dialog_content = "ซะ-เซ-... อะ-เอ่อ หวัดดี ฉันชื่อเซียล... เคยเป็นร่วมชั้นของไวซ์ค่ะ",
  ui_story_5031_50310202_159_dialog_content = "เซ?",
  ui_story_5031_50310202_160_dialog_content = "ไม่เจอกันนานเลยนะ! ที่จริงแล้วนานเกินไปด้วยซ้ำ ไม่ค่อยได้เจอกันเลยตั้งแต่ฉันเริ่มเดินทางกับ PlayerName เนี่ย",
  ui_story_5031_50310202_161_dialog_content = "เซียลค่อนข้างขี้อายน่ะ เวลาพูดตะกุกตะกักจะเหลือแค่ \"เซ\"",
  ui_story_5031_50310202_162_dialog_content = "แต่เรื่องนั้นใครจะไปสนใจล่ะเนอะ? เมื่อก่อนนี้เราเรียกเธอว่าที่สุดแห่งอัจฉริยะ เรื่องวิศวกรรมนี่ได้ทุกอย่างเลย จริงไหม?",
  ui_story_5031_50310202_163_dialog_content = "คนเก่งมาก ๆ ก็จะต้องมีด้านประหลาดอยู่เสมอสินะ",
  ui_story_5031_50310202_164_dialog_content = "เจ้าหน้าที่กรอนรู คุณเซียล มาเที่ยวกันเหรอครับเนี่ย?",
  ui_story_5031_50310202_165_dialog_content = "เปล่า ๆ! ฉันคงไม่สวมชุดหนาเตอะแบบนี้หรอกถ้าจะมาเที่ยวงานคาร์นิวัล",
  ui_story_5031_50310202_166_dialog_content = "อย่าบอกนะว่าเคเลสไทต์ของฉันยังไม่เข้าใจอีก? หรือเธอก็เถอะ ไวซ์?",
  ui_story_5031_50310202_167_dialog_content = "เรืออัศจรรย์ลำนี้มันใหญ่โตสุด ๆ... ลองคิดดูสิว่าโครงสร้างจักรกลจะซับซ้อนแล้วก็ล้ำหน้าแค่ไหน!",
  ui_story_5031_50310202_168_dialog_content = "ฉันเลยถือโอกาสทันทีที่ทำได้ ลากเซียลมาด้วย เพื่อจะดูงานศิลปะทางวิศวกรรมชิ้นนี้ให้ละเอียดไงล่ะ",
  ui_story_5031_50310202_169_dialog_content = "น่าเสียดายที่เราหาทางลงไปด้านล่างไม่ได้! แค่เดินดูภายนอกแป๊บเดียวมันไม่ได้ทำให้รู้แจ้งเห็นจริงอะไรเลย",
  ui_story_5031_50310202_170_dialog_content = "พอเรื่องเป็นแบบนี้ มันก็ช่วยไม่ได้ที่เราจะต้องลงแข่ง!",
  ui_story_5031_50310202_171_dialog_content = "เอ่อ ไวซ์ เธอจะช่วยกรอนรูกับเพื่อนของเธอไหม?",
  ui_story_5031_50310202_172_dialog_content = "ไม่เป็นไรหรอกจ้ะ~ ฉันไม่อยากรบกวนแผนการของ \"ทีมโคลอสซัส\" และฉันเชื่อว่าผู้จัดคงยืดหยุ่นได้ในเรื่องจำนวนสมาชิกทีม",
  ui_story_5031_50310202_173_dialog_content = "และฉันเชื่อสุดใจเลยว่าความสามารถของเซียลก็ไม่ได้ด้อยกว่าไวซ์เลย",
  ui_story_5031_50310202_174_dialog_content = "ฉัน เอ่อ ฉันจะพยายามเต็มที่ค่ะ!",
  ui_story_5031_50310202_175_dialog_content = "ถ้างั้นก็ได้เวลาเตรียมตัวสู่เกมการแข่งขันอันน่าทึ่งนี้แล้ว! เดี๋ยวพบกันนะ",
  ui_story_5031_50310202_176_dialog_content = "ตายแล้ว แค่นี้ก็เจอคู่แข่งโหด ๆ ซะแล้วนะนี่...",
  ui_story_5031_50310202_177_dialog_content = "ทำไมเขาประกาศรายละเอียดช้าจังเลยเนี่ย?",
  ui_story_5031_50310202_178_dialog_content = "อ๊ะ ฉันว่าฉันเห็นคนเดินขึ้นเวทีไปสองคนนะ",
  ui_story_5031_50310202_179_dialog_content = "นั่นใช่เจ้าเมืองเอลวิสรึเปล่า? แล้วก็อีกคน สวมชุดดำทั้งชุดเลยใช่ไหมน่ะ?",
  ui_story_5031_50310202_180_dialog_content = "อะแฮ่ม",
  ui_story_5031_50310202_181_dialog_content = "ยินดีต้อนรับทุกคน! ประชาชนที่รักแห่งเมืองฮาร์เบอร์ และนักท่องเที่ยวจากทั่วทุกสารทิศ!",
  ui_story_5031_50310202_182_dialog_content = "ข้าคือเจ้าเมืองฮาร์เบอร์ เอลวิส โมดาลี",
  ui_story_5031_50310202_183_dialog_content = "เจ้าเมืองเอลวิส!",
  ui_story_5031_50310202_184_dialog_content = "เอลวิส โมดาลี! เอลวิส โมดาลี!",
  ui_story_5031_50310202_185_dialog_content = "ขอบใจมาก และเป็นเกียรติของข้าอย่างยิ่งที่จะเชิญให้ตำนานตัวจริงแห่งท้องทะเลได้มาพบกับพวกเรากลางฤดูร้อนแบบนี้...",
  ui_story_5031_50310202_186_dialog_content = "คณะละครสัตว์นักมายากลและผู้เฒ่าบิลล์จะจัดการแสดงครั้งยิ่งใหญ่ขึ้นอีกครั้งที่งานคาร์นิวัลในครั้งนี้!",
  ui_story_5031_50310202_187_dialog_content = "ผมคือหัวหน้าคณะละครสัตว์นักมายากลและผู้เฒ่าบิลล์ เจโน่ กัลลาเคอร์ ขอบคุณทุกท่านสำหรับการต้อนรับอันอบอุ่น",
  ui_story_5031_50310202_188_dialog_content = "เพื่อความยุติธรรม เป็นธรรมเนียมที่ผมจะต้องแจ้งกฎกติกาให้ทราบสำหรับกิจกรรมต่าง ๆ ในวันนี้",
  ui_story_5031_50310202_189_dialog_content = "ผู้เข้าแข่งขันที่ผ่านภารกิจท้าทายทั้งหมด นอกจากจะได้รับโอกาสสัมผัสประสบการณ์ชีวิตสมาชิกคณะละครสัตว์ถึงหนึ่งวันเต็ม...",
  ui_story_5031_50310202_190_dialog_content = "จะได้รับของขวัญพิเศษอันล้ำค่าที่ผมได้เตรียมไว้ให้ด้วยตัวเองอีกด้วย",
  ui_story_5031_50310202_191_dialog_content = "ดังที่มักเชื่อกันอย่างถูกต้องแล้ว คณะละครสัตว์สัญจรเป็นแหล่งเก็บสะสมของล้ำค่าที่ไม่ธรรมดาจำนวนมากมาย",
  ui_story_5031_50310202_192_dialog_content = "และพูดตามความจริงก็คือ คณะละครสัตว์ที่ผมเป็นผู้ดูแลก็ไม่แตกต่างกัน!",
  ui_story_5031_50310202_193_dialog_content = "การเดินทางที่ยาวไกลของเราเพื่อค้นหาความน่าอัศจรรย์นั้นได้รับพรในรูปแบบต่าง ๆ ที่จับต้องได้และน่าทึ่งอย่างยิ่ง",
  ui_story_5031_50310202_194_dialog_content = "รวมทั้งขุมทรัพย์ทั้งหลายที่อยู่ในท้องทะเล ซึ่งก็คือรางวัลใหญ่ที่สุดของงานคาร์นิวัลในครั้งนี้!",
  ui_story_5031_50310202_195_dialog_content = "ลองนึกภาพขุมทรัพย์ที่แปลกล้ำนี้ได้เลย ลองตั้งใจคาดคิดดูว่ามันคืออะไร พวกคุณไม่ผิดหวังแน่!",
  ui_story_5031_50310202_196_dialog_content = "ว้าว! ฟังดูล้ำค่ามาก!",
  ui_story_5031_50310202_197_dialog_content = "เราต้องรวยกันแน่!",
  ui_story_5031_50310202_197X1_dialog_content = "ขุมทรัพย์แปลกล้ำที่ได้รับมาจากท้องทะเล... ฉันรู้แล้ว!",
  ui_story_5031_50310202_197X2_dialog_content = "ต้องเป็นวา—อุ๊บ!",
  ui_story_5031_50310202_197X3_dialog_content = "จุ๊ ๆ! อย่าเอ็ดไป อยากให้คู่แข่งรู้เข้าและตั้งหน้าตั้งตาแข่งกับเรารึไง?",
  ui_story_5031_50310202_197X4_dialog_content = "อุ๊บ ฉันเข้าใจแล้ว งั้นเราก็ต้องพึ่งตัวเองและเอาชนะการแข่งขันให้ได้ เพื่อช่วยชีวิตวาฬเมฆา!",
  ui_story_5031_50310202_198_dialog_content = "อีกอย่าง ผมว่าพวกคุณคงไม่ชอบใจแน่ถ้าการแข่งขันของเรามีผู้ตัดสินเพียงคนเดียว",
  ui_story_5031_50310202_199_dialog_content = "ด้วยเหตุนี้ ผมจึงมีความยินดีเป็นอย่างยิ่ง ที่ผู้นำที่ยิ่งใหญ่แห่งเมืองฮาร์เบอร์ เจ้าเมืองเอลวิส ได้ตอบรับคำเชิญร่วมมาเป็นผู้ตัดสินกับผม!",
  ui_story_5031_50310202_200_dialog_content = "เจ้าเมืองเอลวิส! เจ้าเมืองเอลวิส!",
  ui_story_5031_50310202_201_dialog_content = "เอ่อ...? เจโน่? เรื่องแบบนี้ควรคุยกันไว้ก่อนไม่ใช่เหรอ?",
  ui_story_5031_50310202_202_dialog_content = "มีปัญหาอะไรรึเปล่า? เรื่องบ้านเมืองน่ารำคาญนั่นลืม ๆ ไปก่อนก็ได้น่า นายเองก็มีสิทธิ์มีความสุขเหมือนกันนะ",
  ui_story_5031_50310202_203_dialog_content = "เจ้าเมืองเอลวิส! เจ้าเมืองเอลวิส!",
  ui_story_5031_50310202_204_dialog_content = "...ก็ได้ เข้าใจแล้ว",
  ui_story_5031_50310202_205_dialog_content = "มาสนุกกันให้เต็มที่เถอะนะ ทุกท่าน!",
