  ui_story_5031_50310402_19_dialog_content = "\"ผู้เข้าแข่งขันโปรดทราบ! เรากำลังจะเข้าสู่ช่วงที่น่าตื่นเต้นยิ่งกว่าเดิมในการแข่งขันของเรา ซึ่งจะเพิ่มภาพลวงตาอิคลิพไซท์เป็นสองเท่า!\"",
  ui_story_5031_50310402_20_dialog_content = "ซะที! ~รอบโบนัสมาแล้ว!",
  ui_story_5031_50310402_21_dialog_content = "คุ้มกันฉันด้วยนะเซียล! รอบโบนัสนี่แหละคือช่วงที่แชมเปี้ยนจะได้ขึ้นนำ หรือไม่ก็ดับสนิท!",
  ui_story_5031_50310402_22_dialog_content = "ขะ-เข้าใจแล้วค่ะ เจ้าหน้าที่กรอนรู",
  ui_story_5031_50310402_23_dialog_content = "เอ๊ะ คุณวิ่งเร็วไปแล้วค่ะ ฉันไม่—",
  ui_story_5031_50310402_24_dialog_content = "เฮ่ย! ใครน่ะ?",
  ui_story_5031_50310402_25_dialog_content = "อะไรเนี่ย? เด็กผู้หญิงจากอิลลูมินา มาคนเดียวเดี่ยว ๆ เลยด้วย",
  ui_story_5031_50310402_26_dialog_content = "ต-ต้องการอะไรกับฉันน่ะ!",
  ui_story_5031_50310402_27_dialog_content = "เราต้องการรางวัลทั้งหมดนั่นแหละ มาขายแลกเงินไงล่ะ",
  ui_story_5031_50310402_28_dialog_content = "โทษทีนะน้องสาว ขอยึดปืนฉีดน้ำเธอได้มั้ย ไม่งั้นพวกเราจะจับเธอโยนลงทะเลซะ",
  ui_story_5031_50310402_29_dialog_content = "เดี๋ยวซิ อุปกรณ์ดูดีนะนั่น! แบบนี้ขายที่อัมบราตันได้ราคาดีเลยนะ ว่าไหม?",
  ui_story_5031_50310402_30_dialog_content = "ใช่แล้ว! และเราน่ะได้อะไรที่อยากได้เสมอนะน้องสาว อย่าทำให้มันยากเลย",
  ui_story_5031_50310402_31_dialog_content = "ส่งของมีค่ามาซะ!",
  ui_story_5031_50310402_32_dialog_content = "ยะ-อย่าเข้ามานะ!",
  ui_story_5031_50310402_33_dialog_content = "หยุดนะ แกสองคน—!",
  ui_story_5031_50310402_34_dialog_content = "อย่าบอกนะว่ายัยพิธีกรนั่นมา!",
  ui_story_5031_50310402_35_dialog_content = "ใช่แล้ว! กติกาการแข่งขันคือห้ามขโมยนะ ฉันคงปล่อยแกสองคนไม่ได้แล้วล่ะ!",
  ui_story_5031_50310402_36_dialog_content = "นี่คิดว่าตัวเองเป็นใคร? คิดว่าเราจะกลัวเพราะเธอเป็นพิธีกรหรือไง?",
  ui_story_5031_50310402_37_dialog_content = "ฉันจะไม่อดทนกับพฤติกรรมง่อย ๆ แบบนี้นะ เข้าใจไหม?",
  ui_story_5031_50310402_38_dialog_content = "<color=#e8d9bb>ปั้ง!</color>",
  ui_story_5031_50310402_39_dialog_content = "พะ-เพื่อน!",
  ui_story_5031_50310402_40_dialog_content = "แกด้วย!",
  ui_story_5031_50310402_41_dialog_content = "<color=#e8d9bb>ปั้ง!</color>",
  ui_story_5031_50310402_42_dialog_content = "โอ๊ย!",
  ui_story_5031_50310402_43_dialog_content = "ย-ยอดเลย... ตกเรือไปดื้อ ๆ เลย",
  ui_story_5031_50310402_44_dialog_content = "เธอไม่ได้เจ็บตัวใช่ไหมจ๊ะ? เจ้าพวกนั้นมันทำเกินไปแล้ว คิดว่าจะมาปล้นใครในกิจกรรมนี้ได้รึไง!",
