  ui_story_5031_50310402_46_dialog_content = "ปืนฉีดน้ำของฉัน... อยู่ที่ไหนเหรอ?",
  ui_story_5031_50310402_47_dialog_content = "อ๋อ โทษทีนะ นี่ รับไว้สิ",
  ui_story_5031_50310402_48_dialog_content = "ฉันเพิ่มกฎใหม่เข้ามา \"ผู้ที่ทำปืนฉีดน้ำหาย สามารถรับปืนใหม่ได้จากพิธีกร\" ดังนั้นไม่ต้องกังวลนะ",
  ui_story_5031_50310402_49_dialog_content = "อ๋อ โอเค! ขอบคุณนะ",
