  ui_story_5031_50310402_54_dialog_content = "คุณพระช่วย ท่านหญิงผู้สูงศักดิ์อย่างคาร์ลีนมาทำอะไรในกิจกรรมแบบนี้เนี่ย?",
  ui_story_5031_50310402_55_dialog_content = "โตมาในครอบครัวชั้นสูงน่าจะรู้ดีกว่านี้นะ เธอทำให้พวกเราชาวชนชั้นสูงดูแย่!",
