  ui_story_5031_50310502_54_dialog_content = "ยังไงก็ตาม ออเดอร์เองก็มีหลายกลุ่มย่อย... ฉันเกรงว่าฉันอาจเป็นประเภทที่ \"นอกเรื่อง\" มากที่สุดก็เป็นได้",
