  ui_story_5031_50310502_62_dialog_content = "หรือนายจะใช้พลังทำนายโชคชะตาเพื่อดูว่าอนาคตฉันจะเกิดอะไรขึ้นบ้าง? ฉันว่าฉันอยู่ได้อย่างน้อย ๆ ก็อีก 200 ปีนั่นแหละ",
