  ui_story_5031_50310502_68_dialog_content = "พูดง่าย ๆ ก็คือ พวกเขาผนึกอิคลิพไซท์ไว้ด้วยพันธสัญญาเลือดอะไรสักอย่างนี่แหละ",
  ui_story_5031_50310502_69_dialog_content = "อิคลิพไซท์ที่ได้รับผลกระทบตกอยู่ในสภาวะจำศีลนิ่งสนิท ส่วนเมืองฮาร์เบอร์ก็กลายเป็นสรวงสวรรค์ที่อิคลิพไซท์ไม่อาจเข้าใกล้",
