  ui_story_5031_50310702_96_dialog_content = "เธออาจไม่ได้บาดเจ็บ แต่เรือมรกตนี่คนละเรื่องกันนะ",
  ui_story_5031_50310702_97_dialog_content = "อ๊ะ ฉะ-ฉันขอโทษจริง ๆ!",
  ui_story_5031_50310702_98_dialog_content = "ฉันไม่ได้ตั้งใจ! ฉันยังแก้บั๊กสติกซ์ไม่เสร็จ ไม่นะ เป็นความผิดฉันเองที่ฉันอ่อนแอ...",
  ui_story_5031_50310702_99_dialog_content = "ไม่เป็นไรหรอกน่า ฉันไม่ได้อยากจะโทษใครทั้งนั้น มาคิดกันดีกว่าว่าจะทำยังไงต่อไป",
