  ui_story_5031_50310702_103_dialog_content = "เลิกขอโทษขอโพยได้แล้ว เอาน่า ไม่เป็นไรหรอก!",
  ui_story_5031_50310702_104_dialog_content = "พูดแล้วนึกได้! เดี๋ยวเธอลงแข่งให้เราก็ได้นี่นา รอบต่อไปเป็นการแข่งโต้คลื่น!",
