  ui_story_5031_50310702_119_dialog_content = "คือว่า... ยังไงฉันก็ให้ไม่ได้...",
  ui_story_5031_50310801_1_dialog_content = "อ้าว ทุกคน! ฉันหวังว่าสายลมเย็น ๆ ในฤดูร้อนและผลไม้ฟรีจะทำให้ทุกคนตื่นเต้นกันนะคะ?",
  ui_story_5031_50310801_2_dialog_content = "ท่าทางทุกคนได้พักผ่อนกันอย่างเพียงพอ และพร้อมที่จะแข่งขันรอบต่อไปแล้วนะคะ!",
