  ui_story_5031_50310902_45_dialog_content = "เรามาถึงรอบที่สามกันแล้ว ทุกคนคงรู้กติกากันหมดแล้ว มาเริ่มกันเลย",
  ui_story_5031_50310902_46_dialog_content = "น้ำวนเชี่ยวกราก!",
  ui_story_5031_50310902_47_dialog_content = "โอ้~ เป็นท่าโจมตีที่รุนแรงจัง",
  ui_story_5031_50310902_48_dialog_content = "งั้นฟริเม็ตก็ต้องเอาจริงบ้างสินะ~ ได้เวลาโชว์ไม้ตายจากการฝึกพิเศษแล้ว!",
  ui_story_5031_50310902_49_dialog_content = "แค่กแค่ก... แค่กแค่กแค่ก!",
  ui_story_5031_50310902_50_dialog_content = "เอลวิส! แล้วยาของนายล่ะ?",
  ui_story_5031_50310902_51_dialog_content = "อยู่ใน... กระเป๋าด้านในเสื้อโค้ต",
  ui_story_5031_50310902_52_dialog_content = "อย่าลืมปิดลำโพงล่ะ... แค่ก...",
