  ui_story_5031_50310902_56_dialog_content = "โทษทีนะ ขอผ้าเช็ดหน้าหน่อยสิ",
  ui_story_5031_50310902_57_dialog_content = "ได้ รอเดี๋ยวนะ",
  ui_story_5031_50310902_58_dialog_content = "<color=#e8d9bb>แคล้ง แคล้ง—</color>",
  ui_story_5031_50310902_59_dialog_content = "ชิ มีแต่เรื่องเต็มไปหมด",
