  ui_story_5031_50310902_62_dialog_content = "เอ้า",
  ui_story_5031_50310902_63_dialog_content = "ขอบคุณ... แค่ก แค่ก",
  ui_story_5031_50310902_64_dialog_content = "รอบนี้สนุกดีแฮะ! สู้กันอย่างมันเลย!",
