  ui_story_5031_50310902_72_dialog_content = "ว่าไงหัวหน้า?",
  ui_story_5031_50310902_73_dialog_content = "ช่วยนับคะแนนแทนฉันแป๊บนึงได้มั้ย ฉันจะต้องคุยธุระน่ะ",
