  ui_story_5031_50310902_84_dialog_content = "ทำหน้าแบบนั้นทำไม?",
  ui_story_5031_50310902_85_dialog_content = "ไม่มีอะไร ที่นายพูด มันทำให้ฉันนึกถึงเรื่องตอนเด็ก ๆ ขึ้นมาได้",
