  ui_story_5031_50310902_87_dialog_content = "ถึงนายจะตัวเล็กกว่าฉัน แต่ถึงอย่างนั้น นายก็ยังพยายามอย่างเต็มที่เพื่อช่วยคนอื่น รวมถึงฉันด้วย",
