  ui_story_5031_50311101_83_dialog_content = "พลังแห่งทะเลสีคราม—",
  ui_story_5031_50311101_84_dialog_content = "อันไร้เทียมทาน—",
  ui_story_5031_50311101_85_dialog_content = "<size=45>โทรน!!</size>",
  ui_story_5031_50311101_86_dialog_content = "แสงอะไรเนี่ย มันจ้าซะเหลือเกิน!",
  ui_story_5031_50311101_87_dialog_content = "อึก... แสงอะไรเนี่ย!?",
  ui_story_5031_50311101_88_dialog_content = "ยอดเลยใช่มั้ยล่ะ?",
  ui_story_5031_50311101_89_dialog_content = "แสงนี่จะเป็นไฟส่องสว่างให้โทรน!",
  ui_story_5031_50311101_90_dialog_content = "แบบนี้ฉันก็จะเล่นเซิร์ฟกลางดึกได้!",
  ui_story_5031_50311101_91_dialog_content = "เอ้อ เยี่ยมเลย จ-เจ๋งดีนะ?",
  ui_story_5031_50311101_92_dialog_content = "สุดยอดเลย!",
  ui_story_5031_50311101_93_dialog_content = "มีคนสนใจเยอะขนาดนี้เลยเรอะ!?",
  ui_story_5031_50311101_94_dialog_content = "ยอดไปเลย! ช่วยแสดงให้ดูอีกทีได้มั้ย?",
  ui_story_5031_50311101_95_dialog_content = "อีกทีเหรอ? เอาสิ!",
  ui_story_5031_50311101_96_dialog_content = "ชิ คนแห่กันมาเยอะแยะแบบนี้ พวกนั้นต้องหนีไปแล้วแน่ ๆ",
  ui_story_5031_50311101_97_dialog_content = "ไม่เป็นไร ถึงจะแอบฟังไปก็หยุดพวกเราไม่ได้หรอก",
  ui_story_5031_50311101_98_dialog_content = "กลับกันเถอะ ทุกอย่างจะต้องเป็นไปตามแผน",
  ui_story_5031_50311101_99_dialog_content = "ขอรับ",
  ui_story_5031_50311101_100_dialog_content = "พวกนั้นไปแล้ว ค่อยยังชั่ว",
  ui_story_5031_50311101_101_dialog_content = "ขอบคุณมากเลยนะ กรอนรู",
  ui_story_5031_50311101_102_dialog_content = "หืม? ฉันไปช่วยอะไรนายเหรอ? ขอบคุณทำไมน่ะ?",
  ui_story_5031_50311101_103_dialog_content = "ถ้าเรื่องทุกอย่างจบลง เดี๋ยวเราจะมาขอบคุณนะ",
  ui_story_5031_50311101_104_dialog_content = "แต่ตอนนี้เรามีเรื่องต้องทำ ไว้เจอกัน!",
  ui_story_5031_50311101_105_dialog_content = "เฮ้ ทำไมรีบร้อนขนาดนั้นล่ะ คู่แข่งผู้อ่อนด้อย!?",
  ui_story_5031_50311101_106_dialog_content = "เอาเถอะ อย่างน้อยพวกนั้นก็ไม่ทำสีหน้าเลิ่กลั่กแล้ว",
  ui_story_5031_50311101_107_dialog_content = "คงสนุกกับการแสดงอันยอดเยี่ยมของฉันแน่ ๆ เลย!",
  ui_story_5031_50311101_108_dialog_content = "ลงไปเจอเรื่องวุ่นวายตั้งมากมาย นอกจากจะเสียเวลาแล้ว ยังไม่รู้อีกว่ารางวัลใหญ่คืออะไร",
  ui_story_5031_50311101_109_dialog_content = "ช่วยไม่ได้ เรือลำนี้ใหญ่เกินไป แถมยังมีคนคุ้มกันเพียบ",
  ui_story_5031_50311101_110_dialog_content = "ลำพังเราสองคนยังไงก็ค้นไม่ทั่วหรอก",
  ui_story_5031_50311101_111_dialog_content = "ตอนนี้คงมีทางเดียวก็คือลุยด้วยฝีมือ แล้วก็คว้าอันดับ 1 มาให้ได้!",
  ui_story_5031_50311101_112_dialog_content = "แต่... เราไม่มีเวลาแล้ว...",
  ui_story_5031_50311101_113_dialog_content = "วาฬเมฆาของฉัน... วาฬเมฆาผู้น่าสงสารจะต้อง...",
  ui_story_5031_50311101_114_dialog_content = "ร้องไห้อีกแล้วเรอะ!?",
  ui_story_5031_50311101_115_dialog_content = "PlayerName ฟีญ่า นี่ยังซ้อมอยู่อีกเหรอ?",
  ui_story_5031_50311101_116_dialog_content = "ไปพูดอะไรใจร้ายให้เธอร้องไห้อีกใช่มั้ย?",
  ui_story_5031_50311101_117_option_content = "เปล่าซะหน่อย!",
  ui_story_5031_50311101_118_option_content = "ฉันไม่ได้ทำนะ!",
  ui_story_5031_50311101_119_dialog_content = "บิก้าไม่ร่วมมือ ฟีญ่าก็เลยตื่นตระหนก",
  ui_story_5031_50311101_120_dialog_content = "ไฮไฮ~",
  ui_story_5031_50311101_121_dialog_content = "โฮววว... พวกเขาไม่ได้ชมแกซักหน่อย!",
  ui_story_5031_50311101_122_dialog_content = "ไฮ?",
  ui_story_5031_50311101_123_dialog_content = "แปลกแฮะ นึกว่าฟีญ่าจะสนิทกับมันซะอีก",
  ui_story_5031_50311101_124_dialog_content = "ทำไมจู่ ๆ บิก้าก็ไม่อยากร่วมมือขึ้นมานะ?",
  ui_story_5031_50311101_125_dialog_content = "แล้วเธอไม่ได้คุยกับบิก้าเรื่องนี้เลยเหรอ?",
  ui_story_5031_50311101_126_dialog_content = "ฉ-ฉันลองแล้ว แต่บิก้าไม่ฟังเลย!",
  ui_story_5031_50311101_127_dialog_content = "เธอพูดอะไรกับบิก้าไปบ้าง?",
  ui_story_5031_50311101_128_dialog_content = "ฉันบอกบิก้าว่าให้ร่วมมือกับฉันเพื่อชิงรางวัลสำคัญ",
  ui_story_5031_50311101_129_dialog_content = "แล้วบิก้าตอบมาว่าไง?",
  ui_story_5031_50311101_130_dialog_content = "บิก้าไม่พูดอะไรเลย...",
  ui_story_5031_50311101_131_dialog_content = "แสดงว่าบิก้าไม่ได้ตกลงจะช่วยเลยงั้นเหรอ?!",
  ui_story_5031_50311101_132_dialog_content = "แต่บิก้าสัญญาแล้วว่าจะมาเป็นผู้ช่วยชั่วคราวของฉันนี่นา... ทำไมมันถึงไม่ยอมช่วยล่ะ?!",
  ui_story_5031_50311101_133_dialog_content = "โฮววว!!!",
  ui_story_5031_50311101_134_dialog_content = "เอาล่ะ ไม่ต้องร้องไห้นะ ฟีญ่า... ปัญหานี้มันขึ้นอยู่กับตัวเธอแล้ว",
  ui_story_5031_50311101_135_dialog_content = "ขึ้นอยู่กับฉัน?",
  ui_story_5031_50311101_136_dialog_content = "ถึงบิก้าจะตกลงเป็นคู่หูของเธอ แต่นั่นก็ไม่ได้หมายความว่าเธอจะชี้นิ้วสั่งมันได้ตามใจชอบ",
  ui_story_5031_50311101_137_dialog_content = "ที่เธออยู่ในสถานการณ์แบบนี้ก็เพราะเธอไม่ยอมฟังบิก้าอย่างแท้จริง",
  ui_story_5031_50311101_138_dialog_content = "งั้นฉันควรทำไงดี?",
