  ui_story_5031_50311101_148_dialog_content = "ขอโทษนะ",
  ui_story_5031_50311101_149_dialog_content = "ไฮ ไฮ?",
  ui_story_5031_50311101_150_dialog_content = "(บิก้าเอาอุ้งเท้ามาแนบหู มันอยากให้ฟีญ่าพูดดังกว่านี้งั้นเหรอ?)",
  ui_story_5031_50311101_151_dialog_content = "ฉัน...",
  ui_story_5031_50311101_152_dialog_content = "<size=45>ฉันขอโทษ!</size>",
  ui_story_5031_50311101_153_dialog_content = "ฉันผิดเอง ไม่น่าบังคับแกมาช่วยแสดงเลย แถมยังไม่สนใจว่าแกจะต้องการอะไร...",
  ui_story_5031_50311101_154_dialog_content = "ฉันขอโทษจริง ๆ คราวหน้า... ม-ไม่ ฉันจะไม่มีเรื่องแบบนี้เกิดขึ้นอีกแล้ว!",
  ui_story_5031_50311101_155_dialog_content = "ต่อไปฉันจะถามความรู้สึกของแกก่อน... โฮวว...",
  ui_story_5031_50311101_156_dialog_content = "ไฮ?",
  ui_story_5031_50311101_157_dialog_content = "หลังจากนั้นเหรอ? เอ่อ หลังจากนั้น... เอาเป็นว่า ฉันเลี้ยงของอร่อย ๆ ดีมั้ย?",
  ui_story_5031_50311101_158_dialog_content = "ไฮ~ไฮไฮ?",
  ui_story_5031_50311101_159_dialog_content = "หา? แกอยากได้องุ่นในตำนานของคุณเผิงงั้นเหรอ?",
