  ui_story_5031_50311101_161_dialog_content = "แต่มันแพงสุด ๆ เลยน่ะสิ...",
  ui_story_5031_50311101_162_dialog_content = "ไฮ ไฮ?",
  ui_story_5031_50311101_163_dialog_content = "เปล่า เปล่า! ฉันไม่ได้บ่นนะ!",
  ui_story_5031_50311101_164_dialog_content = "ถ้าแกยกโทษให้ฉัน ฉันก็ยอมซื้อให้ทุกอย่าง ฮือออ...",
