  ui_story_5031_50311101_168_dialog_content = "(บิก้าท่าทางอารมณ์ดีแล้ว ยอมรับคำขอโทษของฟีญ่าแล้วงั้นเหรอ?)",
  ui_story_5031_50311101_169_dialog_content = "ยกโทษให้ฉันจริง ๆ เหรอ? ยอดเลย!",
  ui_story_5031_50311101_170_dialog_content = "ถ้างั้น เรื่องการแสดง...",
  ui_story_5031_50311101_171_dialog_content = "ไฮไฮ~",
  ui_story_5031_50311101_172_dialog_content = "หา?",
  ui_story_5031_50311101_173_dialog_content = "ฟีญ่า บิก้าพูดอะไรเหรอ?",
  ui_story_5031_50311101_174_dialog_content = "มันบอกว่า... \"ก็ขึ้นกับเธอ\"",
  ui_story_5031_50311101_175_dialog_content = "ทำไมกำกวมจัง?!",
  ui_story_5031_50311101_176_dialog_content = "จะไม่เป็นไรจริง ๆ เหรอ? ลองถามบิก้าอีกทีมั้ย?",
  ui_story_5031_50311101_177_dialog_content = "ยังไงซะ ผลการแข่งขันรอบสุดท้ายก็ขึ้นอยู่กับเรื่องนี้...",
  ui_story_5031_50311101_178_dialog_content = "แต่ฉัน...",
  ui_story_5031_50311101_179_dialog_content = "ศึกสุดท้ายกำลังจะเริ่มขึ้นแล้ว! หมดเวลาเตรียมตัวแล้วล่ะ ผู้เข้าแข่งขันทั้งหลาย!",
  ui_story_5031_50311101_180_dialog_content = "หมดเวลาแล้วเรอะ?!",
  ui_story_5031_50311101_181_dialog_content = "ชั่วโมงนึงแล้วเหรอเนี่ย? ไม่มีทางอื่นแล้วสินะ...",
