  ui_story_5031_50311201_5_dialog_content = "และทีมดาวรุ่งที่นำโดยนักสัตว์มหัศจรรย์วิทยามือใหม่ ฟีญ่า!",
  ui_story_5031_50311201_6_dialog_content = "เฮฮฮฮ!",
  ui_story_5031_50311201_7_dialog_content = "คุณผู้ชมให้การต้อนรับอย่างอบอุ่นจริง ๆ เยี่ยมมาก!",
  ui_story_5031_50311201_8_dialog_content = "เอาล่ะ ก่อนเริ่มการแข่งขันอย่างเป็นทางการ มาเพลิดเพลินกับการแสดงเปิดตัวจากหัวหน้าคณะละครสัตว์เจโน่ และสาวน้อยแฝดสามได้เลย!",
  ui_story_5031_50311201_9_dialog_content = "การแสดงแรก หัวหน้าคณะละครสัตว์เจโน่!",
  ui_story_5031_50311201_10_dialog_content = "\"พิธีกรรมพยากรณ์\" คือความสามารถที่ออโรเรียนมากมายต่างแสวงหามาตั้งแต่ยุคโบราณจนถึงปัจจุบัน",
  ui_story_5031_50311201_11_dialog_content = "การสื่อสารกับสิ่งเร้นลับที่อยู่เหนือมิติของเรา และตีความถ้อยคำแห่งอดีตหรืออนาคต...",
  ui_story_5031_50311201_12_dialog_content = "เพื่อที่จะรับรู้ความจริงของหน้าประวัติศาสตร์ หรือแอบมองสิ่งที่จะเกิดขึ้นภายภาคหน้า",
  ui_story_5031_50311201_13_dialog_content = "ในค่ำคืนนี้ ผมจะแสดงพลังโบราณนี้ให้ทุกคนได้ประจักษ์ และตอบคำถามทุกอย่างที่คุณสงสัย",
  ui_story_5031_50311201_14_dialog_content = "ไพ่แห่งต้นกำเนิดสำรับนี้จะเป็นผู้ช่วยของผม",
  ui_story_5031_50311201_15_dialog_content = "โอ้! นั่นไง! พิธีกรรมพยากรณ์ในตำนาน!",
  ui_story_5031_50311201_16_dialog_content = "เรียกอิคลิพไซท์ได้แถมยังทำนายอนาคตได้อีก พลังแห่งต้นกำเนิดนี่มันคืออะไรกันนะ?",
  ui_story_5031_50311201_17_dialog_content = "ต่อไป ผมต้องขอความร่วมมือจากผู้ชมผู้โชคดีของเรา",
  ui_story_5031_50311201_18_dialog_content = "ใครกันจะได้เป็นอาคันตุกะแห่งโชคชะตา ผู้มีโอกาสได้พบพานผมกันนะ?",
  ui_story_5031_50311201_19_dialog_content = "ฉันเอง!!!",
  ui_story_5031_50311201_20_dialog_content = "ฉันไง! เลือกฉันสิ!",
  ui_story_5031_50311201_21_dialog_content = "รู้แล้ว ผมสัมผัสได้แล้ว...",
  ui_story_5031_50311201_22_dialog_content = "ไพ่แห่งต้นกำเนิดได้ชี้นำโชคชะตาของผมไปหา... คุณ!",
