  ui_story_5031_50311201_26_dialog_content = "คุณสามารถถามคำถามอะไรก็ได้ และผมจะตอบด้วยไพ่แห่งต้นกำเนิด",
  ui_story_5031_50311201_27_dialog_content = "อะไรก็ได้เลยเหรอ?",
  ui_story_5031_50311201_28_dialog_content = "อะไรก็ได้ครับ",
  ui_story_5031_50311201_29_dialog_content = "งั้น... คุณรู้มั้ยว่าฉันมาจากไหน?",
  ui_story_5031_50311201_30_dialog_content = "โอ ไพ่แห่งต้นกำเนิด จงเป็นดวงตาของข้าและมอบนิมิตแห่งความจริง! บอกข้าเถิด ว่าหญิงสาวผู้นี้มาจากที่ใด!",
  ui_story_5031_50311201_31_dialog_content = "(ไพ่เต้นระบำระหว่างนิ้วมือของเจโน่ แล้วเขาก็หยิบไพ่ขึ้นมาหนึ่งใบ!)",
  ui_story_5031_50311201_32_dialog_content = "ไพ่แห่งต้นกำเนิดมอบคำตอบให้ผมแล้ว คุณมาจากเมืองเพเทียเบิร์ก",
  ui_story_5031_50311201_33_dialog_content = "รู้ได้ยังไงน่ะ?!",
  ui_story_5031_50311201_34_dialog_content = "ไพ่แห่งต้นกำเนิดมอบคำตอบนั้นให้ผม ไม่เพียงเท่านั้น มันยังบอกเรื่องอื่นให้ผมรู้อีกด้วย—",
  ui_story_5031_50311201_35_dialog_content = "คุณมาจากตระกูลของไวเคานต์ และมีครอบครัวที่แสนสุข",
  ui_story_5031_50311201_36_dialog_content = "อย่างไรก็ตาม ด้วยเหตุผลบางอย่างทำให้คุณไม่ได้นั่งอยู่กับคู่รัก แต่ความสัมพันธ์ระหว่างคุณกับเขาก็ยังมั่นคงดี",
  ui_story_5031_50311201_37_dialog_content = "ยอดเลย...",
  ui_story_5031_50311201_38_dialog_content = "ตั๋วที่นี่ขายหมดเร็วมาก ทำให้เราต้องนั่งแยกกัน",
  ui_story_5031_50311201_39_dialog_content = "และคู่รักของคุณก็ดึงดันมอบที่นั่งแถวหน้าให้",
  ui_story_5031_50311201_40_dialog_content = "ช-ใช่ค่ะ",
  ui_story_5031_50311201_41_dialog_content = "ไพ่แห่งต้นกำเนิดขออวยพรให้คุณมีชีวิตรักที่มีความสุข! ขอเชิญกลับที่นั่งได้เลยครับ",
  ui_story_5031_50311201_42_dialog_content = "โอ้โห! สุดยอดเลย!!!",
  ui_story_5031_50311201_43_dialog_content = "เลือกอีกคนสิ! เลือกฉันที!",
  ui_story_5031_50311201_44_dialog_content = "เวลาเป็นสิ่งที่ล้ำค่านัก แม้แต่ไพ่แห่งต้นกำเนิดเองก็ต้องเคารพกฎแห่งเวลาเช่นกัน",
  ui_story_5031_50311201_45_dialog_content = "เพราะฉะนั้น ขอให้สนุกกับการแสดงช่วงต่อไป ผมหวังว่าชะตาของเราจะต้องกันอีกครั้ง",
  ui_story_5031_50311201_46_dialog_content = "ช่างเป็นการแสดงอันยอดเยี่ยมจริง ๆ หัวหน้าคณะละครสัตว์เจโน่!",
  ui_story_5031_50311201_47_dialog_content = "ต่อไป ขอเชิญเพลิดเพลินกับการแสดงชิงช้าเหินฟ้าสุดระทึกจากเมอรีลท์ ซับลี่ และฟริเม็ต!",
  ui_story_5031_50311201_48_dialog_content = "เอาล่ะ... ไปกันเถอะ!",
  ui_story_5031_50311201_49_dialog_content = "ให้พวกนั้นอ้าปากค้างไปเลย!",
  ui_story_5031_50311201_50_dialog_content = "โอเค!",
  ui_story_5031_50311201_51_dialog_content = "เริ่มได้!",
  ui_story_5031_50311201_52_dialog_content = "(เมอรีลท์ปีนบันไดแล้วยื่นมือไปหาอีกสองคน)",
  ui_story_5031_50311201_53_dialog_content = "ฮึบ!",
  ui_story_5031_50311201_54_dialog_content = "ฟริเม็ต อย่าปล่อยฉันนะ!",
  ui_story_5031_50311201_55_dialog_content = "ซับลี่... เธอตัวหนักจัง...",
  ui_story_5031_50311201_56_dialog_content = "(เกือบไปแล้ว! ดีนะที่ฟรีเม็ตรับซับลี่ได้!)",
  ui_story_5031_50311201_57_dialog_content = "ฉ-ฉันจะไปแล้วนะ!",
  ui_story_5031_50311201_58_dialog_content = "(หืม? พวกนั้นจะ...?)",
  ui_story_5031_50311201_59_dialog_content = "ฮึบ!!",
  ui_story_5031_50311201_60_dialog_content = "ฉันรับเอง!",
  ui_story_5031_50311201_61_dialog_content = "นี่มัน... หนักขึ้นไปอีก!",
  ui_story_5031_50311201_62_dialog_content = "สำเร็จ!",
  ui_story_5031_50311201_63_option_content = "ยอดเลย!",
  ui_story_5031_50311201_64_dialog_content = "โอ้โหหห! สุดยอดเลย!",
  ui_story_5031_50311201_65_dialog_content = "ข-ขอบคุณทุกคนค่ะ!",
  ui_story_5031_50311201_66_dialog_content = "พวกเราน่ารักมั้ยคะ?",
  ui_story_5031_50311201_67_dialog_content = "น่ารักกกก!",
  ui_story_5031_50311201_68_dialog_content = "นี่เป็นแค่การแสดงธรรมดาเท่านั้น...",
  ui_story_5031_50311201_69_dialog_content = "แต่ถ้าทุกคนสนุก เราก็ดีใจมากเลย!",
  ui_story_5031_50311201_70_dialog_content = "เตรียมชมการแข่งขันนัดต่อไปกันเลย!",
  ui_story_5031_50311201_71_dialog_content = "ขอบคุณสำหรับการแสดงอันยอดเยี่ยมนะทุกคน!",
  ui_story_5031_50311201_72_dialog_content = "ได้เวลาแล้ว... การแข่งขันรอบสุดท้าย เริ่มได้!",
  ui_story_5031_50311201_73_dialog_content = "ทีมแรกคือทีมอิลลูมินา กรอนรูกับเซียลจะแสดงโชว์พิเศษให้พวกคุณดู!",
  ui_story_5031_50311201_74_dialog_content = "ฉันดัดแปลงหุ่นตามความเห็นของคุณกรอนรู เพื่อช่วงเวลานี้...",
  ui_story_5031_50311201_75_dialog_content = "ได้ผลทีเถอะ ได้โปรด!",
  ui_story_5031_50311201_76_dialog_content = "โอ้โห! ดูเหมือนเซียลจะเตรียมตัวมาดีสุด ๆ!",
  ui_story_5031_50311201_77_dialog_content = "...",
  ui_story_5031_50311201_78_dialog_content = "หืม? ฟีญ่า? เป็นอะไรไป? ทำไมตัวสั่นแบบนั้นล่ะ?",
  ui_story_5031_50311201_79_dialog_content = "ตื่นเต้นจัง...",
  ui_story_5031_50311201_80_dialog_content = "ตื่นเต้นเหรอ?",
  ui_story_5031_50311201_81_dialog_content = "ป-เปล่าซะหน่อย!",
  ui_story_5031_50311201_82_dialog_content = "ฉันเป็นนักสัตว์มหัศจรรย์วิทยา! ไม่มีทางอยู่แล้วที่ฉันจะ—โอ๊ย!",
  ui_story_5031_50311201_83_dialog_content = "ตื่นเต้นจนกัดลิ้นเลยเหรอเนี่ย...",
  ui_story_5031_50311201_84_dialog_content = "ก็บอกว่าไม่ได้ตื่นเต้นไง!",
  ui_story_5031_50311201_85_dialog_content = "ฟีญ่า ไม่ต้องคิดอะไรแล้วนะ หายใจลึก ๆ สิ",
  ui_story_5031_50311201_86_dialog_content = "*หายใจเข้า*",
  ui_story_5031_50311201_87_dialog_content = "*หายใจออก*",
  ui_story_5031_50311201_88_dialog_content = "ดีขึ้นมั้ย?",
  ui_story_5031_50311201_89_dialog_content = "แย่แล้ว... ไม่ได้ช่วยเลย หัวใจเต้นแรงกว่าเดิมอีก!",
  ui_story_5031_50311201_90_dialog_content = "เซียลกับกรอนรูท่าทางแข็งแกร่งมาก ๆ แต่ฉันยังไม่รู้ด้วยซ้ำว่าจะให้บิก้าร่วมมือยังไง...",
  ui_story_5031_50311201_91_dialog_content = "ยังไงเราก็ไม่มีทางชนะแน่ ๆ!",
  ui_story_5031_50311201_92_dialog_content = "อย่าตระหนกสิ คิดเรื่องนั้นไปก็ไม่มีประโยชน์หรอก",
  ui_story_5031_50311201_93_dialog_content = "โฟกัสแค่เรื่องที่เธอต้องทำก็พอแล้ว คิดแค่เรื่องการแสดงก็พอ",
  ui_story_5031_50311201_94_dialog_content = "แล้วถ้าบิก้าไม่ร่วมมือด้วยล่ะ?",
  ui_story_5031_50311201_95_dialog_content = "เอ่อ...",
  ui_story_5031_50311201_96_option_content = "เคยได้ยินสุภาษิตที่เค้าพูดกันมั้ย?",
  ui_story_5031_50311201_97_dialog_content = "อันไหนล่ะ?",
  ui_story_5031_50311201_98_dialog_content = "คำชมคือเวทมนตร์วิเศษที่บันดาลทุกสิ่งได้!",
  ui_story_5031_50311201_99_dialog_content = "หา?!",
  ui_story_5031_50311201_100_dialog_content = "จะหมายความว่าไงก็ช่างเถอะ เอาเป็นว่าพยายามทำให้บิก้าอารมณ์ดีก็แล้วกัน ฉันว่ามันน่าจะร่วมมือนะ",
  ui_story_5031_50311201_101_dialog_content = "สิ่งสำคัญที่สุดในตอนนี้คือเราต้องคว้ารางวัลใหญ่ให้ได้ ไม่ว่ามันจะเป็นวาฬเมฆารึเปล่า เรื่องอื่นไม่ต้องไปเก็บมาคิดมากก็ได้!",
  ui_story_5031_50311201_102_dialog_content = "ฉ-ฉันจะลองดู!",
  ui_story_5031_50311201_103_dialog_content = "โชคดีนะ ไวซ์ คาร์ลีน ฉันเองก็จะพยายามทำคะแนนให้เต็มที่!",
  ui_story_5031_50311201_104_dialog_content = "คะแนนท้ายสุดคำนวณโดยการเอาคะแนนทุกคนมาเฉลี่ย",
  ui_story_5031_50311201_105_dialog_content = "เพราะงั้นทุกคนต้องทำให้เต็มที่ถึงจะชนะ!",
  ui_story_5031_50311201_106_dialog_content = "ข-เข้าใจแล้ว...",
  ui_story_5031_50311201_107_dialog_content = "ดูนั่นสิ! ช่างเป็นการแสดงอันน่าเหลือเชื่อจากกรอนรูกับเซียล!",
  ui_story_5031_50311201_108_dialog_content = "เกราะจักรกลของเซียลกับโทรนของกรอนรูกำลังเต้นรำในแสงอันแพรวพราว!",
  ui_story_5031_50311201_109_dialog_content = "หุ่นของเซียลพลิ้วไหวราวกับไร้น้ำหนัก ใช้ทักษะอันเอกอุออกท่าเต้นที่คล้ายการสู้รบ!",
  ui_story_5031_50311201_110_dialog_content = "เธอนำเสนอส่วนผสมที่แสนลงตัวระหว่างความหนักแน่นและความสวยงาม!",
  ui_story_5031_50311201_111_dialog_content = "เอาล่ะ ต่อไปถึงตาของทีมฟีญ่าขึ้นแสดงบทเวทีแล้ว!",
  ui_story_5031_50311201_112_dialog_content = "เธอจะเตรียมการแสดงอันน่าทึ่งอะไรให้พวกเราได้ชมกันนะ?",
  ui_story_5031_50311201_113_dialog_content = "ฟู่... ได้เวลาแล้ว ไปกันเถอะ บิก้า!",
  ui_story_5031_50311201_114_dialog_content = "ไฮ!",
  ui_story_5031_50311201_115_dialog_content = "(โชคดีนะ ฟีญ่า บิก้า!)",
  ui_story_5031_50311201_116_dialog_content = "(ขออย่าให้เกิดเรื่องไม่คาดฝันเลยนะ...)",
  ui_story_5031_50311201_117_dialog_content = "เอาล่ะ! ลุยกันเถอะ! บิก้า ตามฉันมา!",
  ui_story_5031_50311201_118_dialog_content = "ไฮ!",
  ui_story_5031_50311201_119_dialog_content = "เหมือนที่บอกนะบิก้า กระโดดแล้วก็ตีลังกาตกลงไหม?",
  ui_story_5031_50311201_120_dialog_content = "ไฮ ไฮ?",
  ui_story_5031_50311201_121_dialog_content = "(บิก้ากำลังมองฟีญ่าด้วยรอยยิ้มซื่อบื้อ?!)",
  ui_story_5031_50311201_122_dialog_content = "ได้โปรดเถอะ... ร่วมมือกับฉันที!",
  ui_story_5031_50311201_123_dialog_content = "ไฮ?",
  ui_story_5031_50311201_124_dialog_content = "(มันแกล้งทำเป็นไม่รู้เรื่องงั้นเรอะ?!)",
  ui_story_5031_50311201_125_dialog_content = "อะไรกันเนี่ย?",
  ui_story_5031_50311201_126_dialog_content = "เราไม่ได้เสียเงินมาดูพวกเธออยู่เฉย ๆ นะ!",
  ui_story_5031_50311201_127_dialog_content = "ฮึก",
  ui_story_5031_50311201_128_dialog_content = "ด-ได้โปรดเถอะ!",
  ui_story_5031_50311201_129_dialog_content = "ไฮ~?",
  ui_story_5031_50311201_129X1_dialog_content = "บิก้าน่ะเก่งที่สุดแล้ว! เรื่องง่าย ๆ แค่นี้ทำได้สบายอยู่แล้วใช่มั้ยล่ะ!",
  ui_story_5031_50311201_130_dialog_content = "จบงานแข่งแล้วฉันจะซื้อองุ่นลุงเผิงให้นะ!",
  ui_story_5031_50311201_131_dialog_content = "ไฮไฮ!",
  ui_story_5031_50311201_132_dialog_content = "ได้ผลเหรอเนี่ย?!",
  ui_story_5031_50311201_133_dialog_content = "ไฮ~",
  ui_story_5031_50311201_134_dialog_content = "โว้ว! เอาอีก เอาอีก!",
  ui_story_5031_50311201_135_dialog_content = "เอาล่ะ เดี๋ยวฉันจะขว้างบอลไปนะ ช่วยรับที!",
  ui_story_5031_50311201_136_dialog_content = "ไฮ! ไฮ!",
  ui_story_5031_50311201_137_dialog_content = "ไฮ~",
  ui_story_5031_50311201_138_dialog_content = "เยี่ยม!",
  ui_story_5031_50311201_139_dialog_content = "(ยอดเลย บิก้ายอมช่วยฉันแลกกับองุ่น!)",
  ui_story_5031_50311201_140_dialog_content = "ไฮ?",
  ui_story_5031_50311201_141_dialog_content = "เดี๋ยวสิ! นั่นไม่ใช่อาหารนะ!",
  ui_story_5031_50311201_142_dialog_content = "ฮ่าฮ่าฮ่าฮ่าฮ่า!",
  ui_story_5031_50311201_143_dialog_content = "(เกือบไปแล้ว อย่างน้อยคนดูก็คิดว่านั่นเป็นส่วนนึงของโชว์)",
  ui_story_5031_50311201_144_dialog_content = "เอาล่ะ โชว์ไม้ตายลับของแกเลย บิก้า!",
  ui_story_5031_50311201_145_dialog_content = "ไม้ตายลับ? มีด้วยเหรอ?",
  ui_story_5031_50311201_146_dialog_content = "จะให้บิก้ากินหินทั้งก้อนเหมือนตอนที่เราสู้กับนักล่าพวกนั้นน่ะนะ?",
  ui_story_5031_50311201_147_dialog_content = "นั่นมันอันตรายนะ!",
  ui_story_5031_50311201_148_dialog_content = "ฉันไม่ได้จะทำแบบนั้นย่ะ!",
  ui_story_5031_50311201_149_dialog_content = "ฉันเตรียมตัวมาแล้วน่า!",
  ui_story_5031_50311201_150_dialog_content = "เชิญรับชม!",
  ui_story_5031_50311201_151_dialog_content = "ฟองสบู่?",
  ui_story_5031_50311201_152_dialog_content = "ฟองสบู่สวย ๆ เต็มไปหมดเลย!",
  ui_story_5031_50311201_153_dialog_content = "ว่าแต่มันเกี่ยวอะไรกับละครสัตว์ด้วยล่ะ?",
  ui_story_5031_50311201_154_dialog_content = "ฝากด้วยนะบิก้า!",
  ui_story_5031_50311201_155_dialog_content = "ไฮไฮ!",
  ui_story_5031_50311201_156_dialog_content = "ไฮ—!",
  ui_story_5031_50311201_157_dialog_content = "(อ๋อ! ฟองสบู่เป็นทรงกลมแบบที่บิก้าชอบ!)",
  ui_story_5031_50311201_158_dialog_content = "โอ้โห! เจ้าตัวเล็กทำแบบนั้นได้ด้วยเหรอเนี่ย?!",
  ui_story_5031_50311201_159_dialog_content = "ไฮ!",
  ui_story_5031_50311201_160_dialog_content = "ไฮ... ไฮ...",
  ui_story_5031_50311201_161_dialog_content = "*เอิ้ก*",
  ui_story_5031_50311201_162_dialog_content = "(บิก้ากินอากาศเยอะจนตัวพอง!)",
  ui_story_5031_50311201_163_dialog_content = "ฮ่าฮ่าฮ่าฮ่าฮ่า! น่ารักจัง!",
  ui_story_5031_50311201_164_dialog_content = "การแสดงของเราจบลงเพียงเท่านี้!",
  ui_story_5031_50311201_165_dialog_content = "ต่อไปขอเชิญชมการแสดงจากเพื่อนร่วมทีมของเราได้เลย!",
  ui_story_5031_50311201_166_dialog_content = "ว้าว!!!",
  ui_story_5031_50311201_167_dialog_content = "หลังจากฟีญ่าแสดงจบ ฉัน ไวซ์ กับคาร์ลีนก็ขึ้นเวทีแสดงตามลำดับ",
