  ui_story_5031_50311301_7_dialog_content = "ในที่สุดหลาย ๆ เรื่องก็จบได้ซักที...",
  ui_story_5031_50311301_8_dialog_content = "แต่ฉันไม่เจอวาฬเมฆาเลยนะ...",
  ui_story_5031_50311301_9_dialog_content = "วาฬเมฆาในตำนาน แกไปอยู่ที่ไหนกันนะ...?",
  ui_story_5031_50311301_10_dialog_content = "อย่าใจร้อนเลย บางเรื่องเราก็รีบร้อนไม่ได้หรอก",
  ui_story_5031_50311301_11_dialog_content = "ใช่แล้วล่ะ บางทีตอนตื่นนอน ยิ่งฉันรีบหากิ๊บติดผมเท่าไหร่มันก็ยิ่งหาไม่เจอ",
  ui_story_5031_50311301_12_dialog_content = "แต่พอล้มเลิกความตั้งใจ จู่ ๆ ก็เห็นว่ามันมาโผล่ข้าง ๆ ซะยังงั้น!",
  ui_story_5031_50311301_13_dialog_content = "จริงเหรอ?",
  ui_story_5031_50311301_14_dialog_content = "จริงสิ",
  ui_story_5031_50311301_15_dialog_content = "ก็ได้ คราวนี้ฉันจะเชื่อคุณ",
  ui_story_5031_50311301_16_dialog_content = "สวัสดี ทุกคน",
  ui_story_5031_50311301_17_dialog_content = "อ้าว? คาร์ลีน นี่คุยเสร็จแล้วเหรอ ทำไมเร็วจัง?",
  ui_story_5031_50311301_18_dialog_content = "เปล่า ฉันหาท่านเอลวิสไม่เจอเลย",
  ui_story_5031_50311301_19_dialog_content = "เขาเรียกเจโน่ไปคุยแถว ๆ เวทีนี่?",
  ui_story_5031_50311301_20_dialog_content = "ฉันไปเช็กดูแล้ว แต่ไม่เจอพวกเขาเลย",
  ui_story_5031_50311301_21_dialog_content = "เอลวิสกับเจโน่...",
  ui_story_5031_50311301_22_dialog_content = "หรือจะไปที่ด้านในเรือกันนะ?",
  ui_story_5031_50311301_23_dialog_content = "ห้องพัก? เจโน่ไม่ยอมให้ใครเข้าใกล้เลยนี่นา?",
  ui_story_5031_50311301_24_dialog_content = "แต่ถ้าหาที่อื่นไม่เจอ มันก็น่าจะเหลือแค่ที่นั่นแหละ",
  ui_story_5031_50311301_25_dialog_content = "งั้นไปดูกันเถอะ อาจจะมีคนอื่นที่รู้ก็ได้",
  ui_story_5031_50311301_26_dialog_content = "ทำไมนายถึงรู้ทางลงไปในเรือดีจัง PlayerName?",
  ui_story_5031_50311301_27_dialog_content = "เพราะฉันกับฟีญ่าเคยโดนเอลวิสกับพาทูไล่ตาแถว ๆ นี้อยู่ตั้งนานน่ะสิ",
  ui_story_5031_50311301_28_dialog_content = "เอลวิสกับพาทู? เกิดเรื่องแบบนั้นได้ยังไงน่ะ?",
  ui_story_5031_50311301_29_dialog_content = "ถ้าจะสรุปสั้น ๆ ก็...",
  ui_story_5031_50311301_30_dialog_content = "ดูสิ PlayerName มีคนหมดสติอยู่ที่พื้น!",
  ui_story_5031_50311301_31_dialog_content = "นั่นมัน... เจโน่นี่นา?!",
  ui_story_5031_50311301_32_dialog_content = "จริงเหรอ? นายจะวาดภาพฉันจริง ๆ นะ?",
  ui_story_5031_50311301_33_dialog_content = "อื้ม... แต่ฉันวาดช้านะ แล้วก็ไม่ได้วาดเก่งขนาดนั้น...",
  ui_story_5031_50311301_34_dialog_content = "ไม่เป็นไร ภาพวาดของเจโน่น่ะ ดีที่สุดสำหรับฉันอยู่แล้ว!",
  ui_story_5031_50311301_35_dialog_content = "เอ่อ งั้นเราเจอกันพรุ่งนี้เช้าที่ท่าเรือนะ ตกลงมั้ย?",
  ui_story_5031_50311301_36_dialog_content = "ทำงานที่ทะเลเสร็จแล้วค่อยวาดก็ได้ เดี๋ยวฉันทำซุปซีฟู้ดให้!",
  ui_story_5031_50311301_37_dialog_content = "ว้าว ซุปซีฟู้ดฝีมือเอลวิส!",
  ui_story_5031_50311301_38_dialog_content = "เยี่ยมเลย~ งั้นตกลงตามนี้!",
  ui_story_5031_50311301_39_dialog_content = "ไว้พรุ่งนี้เจอกันนะ!",
  ui_story_5031_50311301_40_dialog_content = "อื้ม ว-ไว้พรุ่งนี้เจอกัน!",
  ui_story_5031_50311301_41_dialog_content = "...",
  ui_story_5031_50311301_42_dialog_content = "......",
  ui_story_5031_50311301_43_dialog_content = "เราสัญญากันแล้ว",
  ui_story_5031_50311301_44_dialog_content = "เราสัญญากันแล้วนะ...",
  ui_story_5031_50311301_45_dialog_content = "<size=33>เจ...</size>",
  ui_story_5031_50311301_46_dialog_content = "<size=33>เจโน่...</size>",
  ui_story_5031_50311301_47_dialog_content = "หืม? ใครน่ะ?",
  ui_story_5031_50311301_48_dialog_content = "เจโน่!",
  ui_story_5031_50311301_49_dialog_content = "เอลวิส? นั่นนายเหรอ? นายกลับมาแล้วใช่มั้ย?",
  ui_story_5031_50311301_50_dialog_content = "<size=45>ฟื้นสิ คุณเจโน่!</size>",
  ui_story_5031_50311301_51_dialog_content = "เอลวิส!",
  ui_story_5031_50311301_52_dialog_content = "หวาา!",
  ui_story_5031_50311301_53_dialog_content = "หวาา!",
  ui_story_5031_50311301_54_dialog_content = "นายจะตะโกนทำไมน่ะ PlayerName? ฉันตกใจหมดเลย!",
  ui_story_5031_50311301_55_dialog_content = "ท-โทษที ฉันก็ตกใจเหมือนกัน",
  ui_story_5031_50311301_56_dialog_content = "เป็นไงบ้างคะ คุณเจโน่? บาดเจ็บตรงไหนรึเปล่า?",
  ui_story_5031_50311301_57_dialog_content = "ฉัน... ฉันมาทำอะไรตรงนี้เนี่ย?",
  ui_story_5031_50311301_58_dialog_content = "เราน่าจะเป็นฝ่ายถามคุณนะ?",
  ui_story_5031_50311301_59_dialog_content = "มานอนหลับตรงนี้ทำไม? เราตามหาคุณให้ทั่วเลยรู้มั้ย?",
  ui_story_5031_50311301_60_dialog_content = "เอ่อ นี่มันไม่ใช่ \"นอนหลับ\" นะ ฟีญ่า...",
  ui_story_5031_50311301_61_dialog_content = "โชว์ดอกไม้ไฟกับงานเลี้ยงจบลงแล้ว พวกเราก็เลยอยากจะบอกลาท่านเอลวิส",
  ui_story_5031_50311301_62_dialog_content = "แต่ตามหาที่ไหนก็หาไม่เจอ ก็เลยคิดว่าพวกคุณสองคนอาจจะอยู่ในเรือ",
  ui_story_5031_50311301_63_dialog_content = "พอลองลงมาดู ก็เจอคุณหมดสติอยู่ตรงนี้",
  ui_story_5031_50311301_64_dialog_content = "เมื่อกี้นี้... ชิ",
  ui_story_5031_50311301_65_dialog_content = "ที่นี่ไม่มีใครมากวนแน่ มีธุระอะไรเหรอ เอลวิส?",
  ui_story_5031_50311301_66_dialog_content = "ฉันแค่... อยากจะขอบคุณนายน่ะ เจโน่",
  ui_story_5031_50311301_67_dialog_content = "... หืม? ทำไมจู่ ๆ พูดแบบนั้นล่ะ",
  ui_story_5031_50311301_68_dialog_content = "จะขอบคุณฉันเรื่องอะไร?",
  ui_story_5031_50311301_69_dialog_content = "ขอบคุณที่ตอบรับคำเชิญของฉัน และมอบความทรงจำอันแสนวิเศษให้กับให้กับชาวเมืองฮาร์เบอร์",
  ui_story_5031_50311301_70_dialog_content = "สำหรับฉันแล้ว การมาของนาย... มีความหมายกับฉันมาก ๆ",
  ui_story_5031_50311301_71_dialog_content = "ไม่ใช่เรื่องใหญ่อะไรหรอก เราเร่ร่อนไปทั่วอยู่แล้ว จะแสดงที่ไหนมันก็ไม่ต่างกัน",
  ui_story_5031_50311301_72_dialog_content = "แล้วนายก็จ่ายให้ฉันมากเกินพอ ที่จริงฉันควรเป็นฝ่ายขอบคุณนายด้วยซ้ำ",
  ui_story_5031_50311301_73_dialog_content = "ผิดแล้ว เจโน่",
  ui_story_5031_50311301_74_dialog_content = "หนี้ที่ฉันติดค้างนาย ยังไงชีวิตนี้ก็คงไม่มีทางชดใช้ได้หมด",
  ui_story_5031_50311301_75_dialog_content = "หนี้เหรอ? พูดอะไรของนาย—",
  ui_story_5031_50311301_76_dialog_content = "อึก?!",
  ui_story_5031_50311301_77_dialog_content = "ขอโทษนะ",
  ui_story_5031_50311301_78_dialog_content = "แค่ก แค่ก... อ-อะไรกัน...",
  ui_story_5031_50311301_79_dialog_content = "นี่มัน...?",
  ui_story_5031_50311301_80_dialog_content = "เจโน่... ฉันขอโทษจริง ๆ",
  ui_story_5031_50311301_81_dialog_content = "คุณจะบอกว่า ท่านเอลวิสวางยาคุณงั้นเหรอ?",
  ui_story_5031_50311301_82_dialog_content = "ใช่",
  ui_story_5031_50311301_83_dialog_content = "อ้าว? เอลวิสเป็นคนไม่ดีงั้นเหรอ?",
  ui_story_5031_50311301_84_dialog_content = "อย่าด่วนสรุปสิ ฟีญ่า เรายังไม่รู้ความจริงชัดเจนเลย",
  ui_story_5031_50311301_85_dialog_content = "<size=33>บ้าเอ๊ย หายไปแล้ว...</size>",
  ui_story_5031_50311301_86_dialog_content = "เป็นอะไรไป คุณเจโน่? คุณหาอะไรอยู่เหรอ...",
  ui_story_5031_50311301_87_dialog_content = "เหวอ! อะไรน่ะ?",
  ui_story_5031_50311301_88_dialog_content = "เรือ... กำลังโคลง?",
  ui_story_5031_50311301_89_dialog_content = "... ไม่นึกเลยว่าหมอนั่นจะกล้าทำจริง ๆ",
