  ui_story_5031_50311301_93_dialog_content = "...",
  ui_story_5031_50311301_94_dialog_content = "ฉันจนปัญญาแล้ว",
  ui_story_5031_50311301_95_dialog_content = "ถ้าเขาเปิด \"สิ่งนั้น\" ขึ้นมาจริง ๆ ฉันคงต้องขอร้องให้พวกนายทุกคนช่วย",
  ui_story_5031_50311301_96_dialog_content = "สิ่งนั้น?",
  ui_story_5031_50311301_97_dialog_content = "พอฟื้นขึ้นมา กุญแจห้องแกนกลางของเรือที่ฉันพกติดตัวตลอดก็หายไป",
