  ui_story_5031_50311301_107_dialog_content = "เมื่อเปิดใช้งานผู้พิทักษ์แกนพลัง มันก็จะโจมตีสิ่งมีชีวิตทุกชนิดที่เข้าใกล้แกนพลังงานอย่างไม่เลือกหน้า",
